/**
 * Core-loop saves intentionally start clean. The preceding UI controller mixed
 * incompatible stage state into account saves, so loading it would recreate
 * broken progression rather than migrate it.
 */
const SAVE_KEY = "stonesummoner.save.v6";
const DEMO_SAVE_KEY = "stonesummoner.save.demo.v6";
const CORE_LOOP_RESET_KEY = "stonesummoner.core-loop-reset.v1";

const AUTH_PREFS_KEY = "stonesummoner.auth.prefs.v1";

type AuthPrefs = {
  saveId: boolean;
  autoLogin: boolean;
  savedEmail: string;
};

function defaultAuthPrefs(): AuthPrefs {
  return { saveId: true, autoLogin: false, savedEmail: "" };
}

function readAuthPrefs(): AuthPrefs {
  try {
    const raw = localStorage.getItem(AUTH_PREFS_KEY);
    if (!raw) return defaultAuthPrefs();
    const parsed = JSON.parse(raw) as Partial<AuthPrefs>;
    return {
      saveId: parsed.saveId !== false,
      autoLogin: parsed.autoLogin === true,
      savedEmail: typeof parsed.savedEmail === "string" ? parsed.savedEmail : "",
    };
  } catch {
    return defaultAuthPrefs();
  }
}

function writeAuthPrefs(next: AuthPrefs): void {
  localStorage.setItem(AUTH_PREFS_KEY, JSON.stringify(next));
}

function readIslandLayout(): Record<string, { x: number; y: number }> {
  const out: Record<string, { x: number; y: number }> = {
    ...ISLAND_LAYOUT_DEFAULT,
  };
  try {
    const raw = localStorage.getItem(ISLAND_LAYOUT_KEY);
    if (!raw) return out;
    const parsed = JSON.parse(raw) as Record<string, { x?: unknown; y?: unknown }>;
    for (const [id, pos] of Object.entries(parsed)) {
      if (!ISLAND_LAYOUT_DEFAULT[id]) continue;
      const x = Number(pos?.x);
      const y = Number(pos?.y);
      if (!Number.isFinite(x) || !Number.isFinite(y)) continue;
      out[id] = clampIslandLayoutPos(x, y, out, id);
    }
  } catch {
    /* ignore */
  }
  return out;
}

function writeIslandLayout(layout: Record<string, { x: number; y: number }>): void {
  const slim: Record<string, { x: number; y: number }> = {};
  for (const id of Object.keys(ISLAND_LAYOUT_DEFAULT)) {
    const pos = layout[id] ?? ISLAND_LAYOUT_DEFAULT[id]!;
    slim[id] = {
      x: Math.round(pos.x * 10) / 10,
      y: Math.round(pos.y * 10) / 10,
    };
  }
  localStorage.setItem(ISLAND_LAYOUT_KEY, JSON.stringify(slim));
}

function resolveIslandSpotPos(
  id: string,
  fallbackX: number,
  fallbackY: number,
): { x: number; y: number } {
  const src =
    islandLayoutEdit && islandLayoutDraft
      ? islandLayoutDraft
      : readIslandLayout();
  return src[id] ?? ISLAND_LAYOUT_DEFAULT[id] ?? { x: fallbackX, y: fallbackY };
}

function enterIslandLayoutEdit(focusId?: string): void {
  islandLayoutEdit = true;
  islandLayoutDraft = { ...readIslandLayout() };
  islandLayoutSuppressClick = true;
  islandPanDrag = null;
  islandLongPress = null;
  rememberOverlayOpen("island-layout-edit");
  flash(t('ui.19364fa53d'));
  render();
  if (focusId) {
    queueMicrotask(() => {
      app
        .querySelectorAll<HTMLElement>("[data-b]")
        .forEach((el) =>
          el.classList.toggle("is-layout-focus", el.dataset.b === focusId),
        );
    });
  }
}

function exitIslandLayoutEdit(commit: boolean): void {
  if (commit && islandLayoutDraft) {
    writeIslandLayout(islandLayoutDraft);
    flash(t('ui.3ad18550e0'));
  } else if (!commit) {
    flash(t('ui.5d8b99bb60'));
  }
  islandLayoutEdit = false;
  islandLayoutDraft = null;
  islandSpotDrag = null;
  islandLongPress = null;
  rememberOverlayClose("island-layout-edit");
  clearIslandDropTargets();

  // Soft leave — do not remount via render(). render() would set
  // islandLayoutEdit=false first, then preserve the *old* island DOM that still
  // carries the edit HUD / guides, so Done looked like a no-op.
  const island = app.querySelector<HTMLElement>(".home-island");
  if (island && view === "home") {
    app.classList.remove("island-layout-edit");
    island.querySelector(".island-edit-hud")?.remove();
    island.querySelector(".island-build-guide")?.remove();
    const viewport = island.querySelector<HTMLElement>("#island-viewport");
    viewport?.classList.remove("is-layout-edit", "is-spot-dragging");
    island.querySelectorAll<HTMLElement>("[data-b]").forEach((el) => {
      el.classList.remove("is-layout-edit", "is-layout-focus", "is-dragging");
    });
    return;
  }
  render();
}

function clientToIslandPct(
  clientX: number,
  clientY: number,
  world: HTMLElement,
): { x: number; y: number } {
  const rect = world.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return { x: 50, y: 50 };
  return {
    x: ((clientX - rect.left) / rect.width) * 100,
    y: ((clientY - rect.top) / rect.height) * 100,
  };
}

/** Soft land clamp while dragging — no pad snap (snap only on drop). */
function dragIslandLayoutPos(x: number, y: number): { x: number; y: number } {
  return projectToIslandLand(x, y);
}

function applyIslandSpotPosDom(
  id: string,
  x: number,
  y: number,
  opts?: { snap?: boolean },
): void {
  if (!islandLayoutDraft) islandLayoutDraft = { ...readIslandLayout() };
  const others = { ...islandLayoutDraft };
  delete others[id];
  const pos = opts?.snap
    ? clampIslandLayoutPos(x, y, others, id)
    : dragIslandLayoutPos(x, y);
  islandLayoutDraft[id] = pos;
  const btn = app.querySelector<HTMLElement>(`[data-b="${id}"]`);
  if (!btn) return;
  const depth = Math.max(0, Math.min(1, pos.y / 100));
  btn.style.left = `${pos.x}%`;
  btn.style.top = `${pos.y}%`;
  btn.style.setProperty("--spot-scale", (0.68 + depth * 0.5).toFixed(3));
  btn.style.zIndex = String(Math.round(10 + pos.y));
}

/** Light up the nearest free pad under the dragged spot (drop preview). */
function updateIslandDropTarget(id: string, x: number, y: number): void {
  const layout = islandLayoutDraft ?? {};
  const others = { ...layout };
  delete others[id];
  const target = snapToIslandPad(x, y, others, id);
  app.querySelectorAll<HTMLElement>(".island-landing-pad").forEach((el) => {
    const px = Number(el.dataset.padX);
    const py = Number(el.dataset.padY);
    const hit =
      Number.isFinite(px) &&
      Number.isFinite(py) &&
      Math.abs(px - target.x) < 0.05 &&
      Math.abs(py - target.y) < 0.05;
    el.classList.toggle("is-drop-target", hit);
  });
}

function clearIslandDropTargets(): void {
  app
    .querySelectorAll<HTMLElement>(".island-landing-pad.is-drop-target")
    .forEach((el) => el.classList.remove("is-drop-target"));
}


