/** Swap inspect panes without full app re-render (keeps roster dock intact). */
function applyMonDetailTabUi(): boolean {
  const shell = app.querySelector<HTMLElement>(".mon-inspect-shell");
  if (!shell) return false;
  shell.closest(".mon-inspect")?.classList.toggle(
    "mon-inspect--tab-symbols",
    monDetailTab === "symbols",
  );
  shell.querySelectorAll<HTMLButtonElement>("[data-mon-detail-tab]").forEach((btn) => {
    const on = btn.dataset.monDetailTab === monDetailTab;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  shell.querySelectorAll<HTMLElement>("[data-mon-pane]").forEach((pane) => {
    pane.hidden = pane.dataset.monPane !== monDetailTab;
  });
  return true;
}

let monInspectInteractAbort: AbortController | null = null;

function syncMonRosterActiveSlot(): void {
  app.querySelectorAll<HTMLButtonElement>("[data-select-mon]").forEach((btn) => {
    const on = btn.dataset.selectMon === selectedEnhanceUid;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
}

/** Patch monster inspect + slot highlight without remounting the roster rail. */
function refreshMonInspectSoft(): boolean {
  const viewer = app.querySelector<HTMLElement>(
    ".enhance-screen .mon-book-viewer",
  );
  if (!viewer) return false;
  const rail = app.querySelector<HTMLElement>(
    ".mon-roster-dock .mon-book-inv--rail",
  );
  const keepLeft = rail?.scrollLeft ?? 0;
  viewer.innerHTML = renderMonBookDetailHtml();
  dematteArtInTree(viewer);
  bindMonPreviewTurntable(viewer);
  syncMonRosterActiveSlot();
  bindMonInspectInteractions();
  bindSymbolInventoryInteractions();
  applyMonDetailTabUi();
  if (rail) rail.scrollLeft = keepLeft;
  return true;
}

function bindMonInspectInteractions(): void {
  monInspectInteractAbort?.abort();
  const ac = new AbortController();
  monInspectInteractAbort = ac;
  const opts: AddEventListenerOptions = { signal: ac.signal };
  const host = app.querySelector<HTMLElement>(".enhance-screen .mon-book-viewer");
  if (!host) return;

  host.querySelectorAll<HTMLButtonElement>("[data-enh]").forEach((btn) => {
    btn.addEventListener(
      "click",
      () => {
        const uid = btn.dataset.enh!;
        if (!save.roster.some((monster) => monster.uid === uid)) return;
        selectedEnhanceUid = uid;
        powerUpFodderUids = new Set();
        evolveModalOpen = false;
        evolveFodderUids = new Set();
        applyEvolveOpen();
        powerUpModalOpen = true;
        refreshPowerUpModalDom();
        applyPowerUpOpen();
      },
      opts,
    );
  });

  host.querySelectorAll<HTMLButtonElement>("[data-evolve-open]").forEach((btn) => {
    btn.addEventListener(
      "click",
      () => {
        if (btn.disabled) return;
        const uid = btn.dataset.evolveOpen;
        if (!uid || !save.roster.some((monster) => monster.uid === uid)) return;
        selectedEnhanceUid = uid;
        closeMonRiteModal();
        powerUpModalOpen = false;
        powerUpFodderUids = new Set();
        applyPowerUpOpen();
        evolveFodderUids = new Set();
        evolveModalOpen = true;
        refreshEvolveModalDom();
        applyEvolveOpen();
      },
      opts,
    );
  });

  host.querySelectorAll<HTMLButtonElement>("[data-awaken-open]").forEach((btn) => {
    btn.addEventListener(
      "click",
      () => {
        if (btn.disabled) return;
        const uid = btn.dataset.awakenOpen;
        if (!uid) return;
        evolveModalOpen = false;
        evolveFodderUids = new Set();
        applyEvolveOpen();
        openMonRiteModal("awaken", uid);
      },
      opts,
    );
  });

  host.querySelectorAll<HTMLButtonElement>("[data-mon-detail-tab]").forEach((btn) => {
    btn.addEventListener(
      "click",
      () => {
        const raw = btn.dataset.monDetailTab;
        if (raw === "info" || raw === "symbols") {
          if (monDetailTab === raw) return;
          monDetailTab = raw;
          if (raw !== "symbols") symbolInvFilterOpen = null;
          enhanceTab = "monsters";
          if (!applyMonDetailTabUi()) render();
        }
      },
      opts,
    );
  });

  host.querySelectorAll<HTMLButtonElement>("[data-mon-skill-pick]").forEach((btn) => {
    btn.addEventListener(
      "click",
      () => {
        const slot = Number(btn.dataset.monSkillPick ?? "0");
        if (slot < 0 || slot > 2 || slot === monSkillPick) return;
        monSkillPick = slot;
        monDetailTab = "info";
        enhanceTab = "monsters";
        applyMonDetailTabUi();
        if (!applyMonSkillPickUi()) render();
      },
      opts,
    );
  });
}

/** Swap summoner-book inspect panes without full app re-render. */
function applySumDetailTabUi(): boolean {
  const shell = app.querySelector<HTMLElement>(".sum-inspect-shell");
  if (!shell) return false;
  shell.querySelectorAll<HTMLButtonElement>("[data-sum-detail-tab]").forEach((btn) => {
    const on = btn.dataset.sumDetailTab === sumDetailTab;
    btn.classList.toggle("is-active", on);
    btn.setAttribute("aria-selected", on ? "true" : "false");
  });
  shell.querySelectorAll<HTMLElement>("[data-sum-pane]").forEach((pane) => {
    pane.hidden = pane.dataset.sumPane !== sumDetailTab;
  });
  if (sumDetailTab === "gear") {
    refreshSumGearPane();
  } else if (gearBagFilterOpen) {
    gearBagFilterOpen = false;
    clearGearBagFilterMenuPortal();
    refreshSumGearPane();
  }
  return true;
}

function activeSummonerElement(): SummonerElement {
  return (save.activeSummoner ?? "light") as SummonerElement;
}

function syncSumMagicNodeActive(): void {
  app.querySelectorAll<HTMLButtonElement>("[data-magic-detail-slot]").forEach((btn) => {
    btn.classList.toggle(
      "is-active",
      btn.dataset.magicDetailSlot === sumMagicDetailSlot,
    );
  });
}

/** Soft-patch summoner book modals without rebuilding hub sky / screen. */
function refreshSumBookModals(): boolean {
  const host = app.querySelector<HTMLElement>("#sum-modal-host");
  const onBook = !!host || !!app.querySelector(".sum-screen");
  if (host) host.innerHTML = "";
  const el = activeSummonerElement();
  softRemoveOverlay("gear-detail-layer");
  softRemoveOverlay("sum-magic-detail-layer");
  if (gearSellConfirmIndex == null || !save.gearBag?.[gearSellConfirmIndex]) {
    gearSellConfirmIndex = null;
    softRemoveOverlay("gear-sell-confirm-layer");
  }
  if (gearEnhanceConfirmSlot == null || !getActiveGear(save)[gearEnhanceConfirmSlot]) {
    gearEnhanceConfirmSlot = null;
    softRemoveOverlay("gear-enhance-confirm-layer");
  }
  const gear = renderGearDetailModal(el);
  const magic = renderSumMagicDetailModal(el);
  if (gear) softMountOverlay("gear-detail-layer", gear);
  if (magic) softMountOverlay("sum-magic-detail-layer", magic);
  if (gearSellConfirmIndex != null && save.gearBag?.[gearSellConfirmIndex]) {
    softMountOverlay("gear-sell-confirm-layer", renderGearSellConfirmModal());
  }
  if (gearEnhanceConfirmSlot != null && getActiveGear(save)[gearEnhanceConfirmSlot]) {
    softMountOverlay("gear-enhance-confirm-layer", renderGearEnhanceConfirmModal());
  }
  softRemoveOverlay("gear-bag-expand-layer");
  const gearExpand = renderGearBagExpandModal();
  if (gearExpand) softMountOverlay("gear-bag-expand-layer", gearExpand);
  syncSumMagicNodeActive();
  bindSumBookModalInteractions();
  bindGearBagExpandModal();
  return onBook;
}

function refreshSumGearPane(): boolean {
  const pane = app.querySelector<HTMLElement>('[data-sum-pane="gear"]');
  if (!pane) return false;
  pane.innerHTML = renderGearDollHtml(activeSummonerElement());
  dematteArtInTree(
    pane,
    "img.gear-slot-ico, .gear-bag-slot:not(.gear-bag-slot--empty) img",
  );
  bindSumGearSlotClicks();
  bindGearBagFilter();
  bindGearBagExpandButton();
  syncGearBagFilterMenuUi();
  queueMicrotask(() => {
    enhanceFx = null;
  });
  return true;
}

function bindGearBagExpandButton(): void {
  app.querySelector("[data-expand-gear-bag]")?.addEventListener("click", () => {
    if (gearBagExpandCost(save) == null) return;
    gearDetailTarget = null;
    gearSellConfirmIndex = null;
    gearBagFilterOpen = false;
    gearBagExpandOpen = true;
    softRefreshSumBookUi({ modals: true });
  });
}

function bindGearBagExpandModal(): void {
  const close = () => {
    if (!gearBagExpandOpen) return;
    gearBagExpandOpen = false;
    softRefreshSumBookUi({ modals: true });
  };
  app.querySelectorAll("#btn-gear-bag-expand-close").forEach((el) => {
    el.addEventListener("click", close);
  });
  app.querySelector("#btn-gear-bag-expand-cancel")?.addEventListener("click", close);
  app.querySelector("#btn-gear-bag-expand-ok")?.addEventListener("click", () => {
    const cost = gearBagExpandCost(save);
    if (cost == null || save.island.crystal < cost) return;
    const r = runExpandGearBag(save);
    if (r.save === save) return;
    save = r.save;
    persist();
    syncHudResources();
    gearBagExpandOpen = false;
    softRefreshSumBookUi({ gear: true, modals: true });
  });
}

function renderGearBagExpandModal(): string {
  if (!gearBagExpandOpen) return "";
  const cur = gearBagCapacity(save);
  const cost = gearBagExpandCost(save);
  if (cost == null) return "";
  const add = GEAR_BAG_EXPAND_STEP;
  const next = Math.min(GEAR_BAG_MAX_SLOTS, cur + add);
  const canPay = save.island.crystal >= cost;
  return `<div class="settings-layer gear-bag-expand-layer" id="gear-bag-expand-layer" aria-hidden="false">
    <button type="button" class="settings-backdrop" id="btn-gear-bag-expand-close" aria-label="close"></button>
    <div class="sym-bag-expand-sheet" role="dialog" aria-modal="true" aria-labelledby="gear-bag-expand-title">
      ${modalCloseX("close", "btn-gear-bag-expand-close")}
      <h3 class="sym-bag-expand-title" id="gear-bag-expand-title">${escapeHtml(t("ui.expandGearBagTitle"))}</h3>
      <div class="sym-bag-expand-rows">
        <div class="sym-bag-expand-row">
          <span>${escapeHtml(t("ui.expandSymbolBagCurrent"))}</span>
          <strong>${cur}</strong>
        </div>
        <div class="sym-bag-expand-row">
          <span>${escapeHtml(t("ui.expandSymbolBagAdd"))}</span>
          <strong>+${add} ${MIDDOT} ${next}</strong>
        </div>
      </div>
      <div class="sym-bag-expand-acts">
        <button type="button" class="secondary" id="btn-gear-bag-expand-cancel">${escapeHtml(t("ui.19b2d19bc1"))}</button>
        <button type="button" class="sym-bag-expand-ok" id="btn-gear-bag-expand-ok" ${canPay ? "" : "disabled"}>
          <span>${escapeHtml(t("ui.expandSymbolBagConfirm"))}</span>
          ${shopPriceCrystal(cost)}
        </button>
      </div>
    </div>
  </div>`;
}

function refreshSumSkillsPane(): boolean {
  const body = app.querySelector<HTMLElement>("[data-sum-skills-body]");
  if (!body) return false;
  body.innerHTML = renderSumMagicTreeHtml(activeSummonerElement());
  bindSumMagicNodeClicks();
  return true;
}

function softRefreshSumBookUi(opts?: {
  gear?: boolean;
  skills?: boolean;
  modals?: boolean;
}): void {
  const wantGear = opts?.gear ?? false;
  const wantSkills = opts?.skills ?? false;
  const wantModals = opts?.modals ?? true;
  let ok = true;
  if (wantGear) ok = refreshSumGearPane() && ok;
  if (wantSkills) ok = refreshSumSkillsPane() && ok;
  if (wantModals) ok = refreshSumBookModals() && ok;
  if (!ok) render();
}

function bindSumGearSlotClicks(): void {
  const root = app.querySelector(".sum-screen") ?? app;
  root.querySelectorAll<HTMLButtonElement>("[data-gear-detail-slot]").forEach((btn) => {
    btn.addEventListener("click", () => {
      gearBagFilterOpen = false;
      clearGearBagFilterMenuPortal();
      gearDetailTarget = {
        kind: "equipped",
        slot: parseGearSlot(btn.dataset.gearDetailSlot),
      };
      gearDetailHideEquippedCompare = false;
      sumMagicDetailSlot = null;
      softRefreshSumBookUi({ modals: true });
    });
  });

  root.querySelectorAll<HTMLButtonElement>("[data-gear-detail-bag]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const index = Number(btn.dataset.gearDetailBag ?? "-1");
      if (!Number.isInteger(index) || index < 0 || !save.gearBag?.[index]) return;
      gearBagFilterOpen = false;
      clearGearBagFilterMenuPortal();
      gearDetailTarget = { kind: "bag", index };
      gearDetailHideEquippedCompare = false;
      sumMagicDetailSlot = null;
      softRefreshSumBookUi({ modals: true });
    });
  });
}

function clearGearBagFilterMenuPortal(): void {
  document.querySelectorAll("body > .mon-sym-filter-menu[data-gear-filter-menu]").forEach((el) =>
    el.remove(),
  );
}

function placeGearBagFilterMenu(): void {
  if (!gearBagFilterOpen) return;
  const btn = app.querySelector<HTMLElement>("[data-gear-filter-toggle]");
  const menu =
    document.querySelector<HTMLElement>("body > .mon-sym-filter-menu[data-gear-filter-menu]") ??
    app.querySelector<HTMLElement>(".mon-sym-filter-menu[data-gear-filter-menu]");
  if (!btn || !menu) return;
  const r = btn.getBoundingClientRect();
  const pad = 8;
  const mw = Math.max(menu.offsetWidth, 160);
  const mh = Math.max(menu.offsetHeight, 40);
  let left = r.right - mw;
  left = Math.min(Math.max(pad, left), Math.max(pad, window.innerWidth - mw - pad));
  let top = r.bottom + 4;
  if (top + mh > window.innerHeight - pad) {
    top = Math.max(pad, r.top - mh - 4);
  }
  menu.style.left = `${Math.round(left)}px`;
  menu.style.top = `${Math.round(top)}px`;
}

function syncGearBagFilterMenuUi(): void {
  gearBagFilterUiAbort?.abort();
  gearBagFilterUiAbort = null;
  clearGearBagFilterMenuPortal();
  if (!gearBagFilterOpen) return;
  const menu = app.querySelector<HTMLElement>(".mon-sym-filter-menu[data-gear-filter-menu]");
  if (!menu) return;
  document.body.appendChild(menu);
  placeGearBagFilterMenu();
  requestAnimationFrame(placeGearBagFilterMenu);
  menu.querySelectorAll<HTMLButtonElement>("[data-gear-filter-slot]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      const raw = btn.dataset.gearFilterSlot ?? "all";
      gearBagFilterSlot = raw === "all" || !isGearSlot(raw) ? "all" : raw;
      gearBagFilterOpen = false;
      if (!refreshSumGearPane()) render();
    });
  });
  const ac = new AbortController();
  gearBagFilterUiAbort = ac;
  const onOutside = (ev: Event) => {
    const target = ev.target as HTMLElement | null;
    if (
      target?.closest?.("[data-gear-filter]") ||
      target?.closest?.("[data-gear-filter-menu]")
    ) {
      return;
    }
    gearBagFilterOpen = false;
    gearBagFilterUiAbort?.abort();
    gearBagFilterUiAbort = null;
    clearGearBagFilterMenuPortal();
    app.querySelectorAll<HTMLButtonElement>("[data-gear-filter-toggle]").forEach((btn) => {
      btn.setAttribute("aria-expanded", "false");
    });
  };
  setTimeout(() => {
    if (ac.signal.aborted) return;
    document.addEventListener("pointerdown", onOutside, {
      capture: true,
      signal: ac.signal,
    });
  }, 0);
  window.addEventListener(
    "resize",
    () => {
      if (gearBagFilterOpen) placeGearBagFilterMenu();
    },
    { signal: ac.signal },
  );
  window.addEventListener(
    "scroll",
    () => {
      if (gearBagFilterOpen) placeGearBagFilterMenu();
    },
    { capture: true, signal: ac.signal },
  );
}

function bindGearBagFilter(): void {
  const root = app.querySelector(".sum-screen") ?? app;
  root.querySelector("[data-gear-filter-toggle]")?.addEventListener("click", (ev) => {
    ev.stopPropagation();
    gearBagFilterOpen = !gearBagFilterOpen;
    if (gearBagFilterOpen) rememberOverlayOpen("gear-bag-filter");
    else rememberOverlayClose("gear-bag-filter");
    if (!refreshSumGearPane()) render();
  });
}

function bindSumMagicNodeClicks(): void {
  const root = app.querySelector(".sum-screen") ?? app;
  root.querySelectorAll<HTMLButtonElement>("[data-magic-detail-slot]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const slot = btn.dataset.magicDetailSlot as MagicSkillSlot | undefined;
      if (!slot || !["A", "B", "A1", "A2", "A3", "A4", "B1", "B2", "B3", "B4"].includes(slot)) return;
      sumMagicDetailSlot = slot;
      closeGearSellConfirm();
      gearDetailTarget = null;
      sumDetailTab = "skills";
      applySumDetailTabUi();
      softRefreshSumBookUi({ modals: true });
    });
  });
}

function bindSumBookModalInteractions(): void {
  const gearLayer = app.querySelector<HTMLElement>("#gear-detail-layer");
  const magicLayer = app.querySelector<HTMLElement>("#sum-magic-detail-layer");

  const closeGearDetail = () => {
    closeGearSellConfirm();
    gearDetailTarget = null;
    gearDetailHideEquippedCompare = false;
    softRefreshSumBookUi({ modals: true });
  };
  gearLayer?.querySelectorAll("#btn-gear-detail-close").forEach((el) => {
    el.addEventListener("click", closeGearDetail);
  });
  gearLayer?.querySelector("#btn-gear-detail-close-equipped")?.addEventListener("click", () => {
    if (!gearDetailTarget || gearDetailTarget.kind !== "bag") return;
    gearDetailHideEquippedCompare = true;
    softRefreshSumBookUi({ modals: true });
  });
  gearLayer?.querySelector("#btn-gear-detail-close-candidate")?.addEventListener("click", () => {
    if (!gearDetailTarget || gearDetailTarget.kind !== "bag") return;
    const bagSource = save.gearBag?.[gearDetailTarget.index];
    if (!bagSource) {
      closeGearDetail();
      return;
    }
    gearDetailHideEquippedCompare = false;
    gearDetailTarget = { kind: "equipped", slot: bagSource.slot };
    softRefreshSumBookUi({ modals: true });
  });

  gearLayer?.querySelectorAll<HTMLButtonElement>("[data-gear-detail-enhance]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const slot = parseGearSlot(btn.dataset.gearDetailEnhance);
      if (!getActiveGear(save)[slot]) return;
      openGearEnhanceConfirm(slot);
    });
  });

  gearLayer?.querySelectorAll<HTMLButtonElement>("[data-gear-detail-unequip]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      const slot = parseGearSlot(btn.dataset.gearDetailUnequip);
      const r = runUnequipGear(save, slot);
      if (getActiveGear(r.save)[slot]) return;
      save = r.save;
      persist();
      closeGearEnhanceConfirm();
      closeGearSellConfirm();
      gearDetailTarget = null;
      softRefreshSumBookUi({ gear: true, modals: true });
    });
  });

  gearLayer?.querySelectorAll<HTMLButtonElement>("[data-gear-detail-equip]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (btn.disabled) return;
      const idx = Number(btn.dataset.gearDetailEquip ?? "-1");
      const bagPiece = save.gearBag?.[idx];
      if (bagPiece) {
        const el = save.activeSummoner ?? "light";
        const norm = normalizeGearPiece(bagPiece, bagPiece.slot);
        if (!canEquipGearOnElement(norm, el)) return;
      }
      const bagLen = (save.gearBag ?? []).length;
      const r = runEquipGearBag(save, idx);
      save = r.save;
      persist();
      if ((save.gearBag ?? []).length < bagLen) {
        patchOnboard({ equipped: true });
      }
      closeGearSellConfirm();
      gearDetailTarget = null;
      softRefreshSumBookUi({ gear: true, modals: true });
    });
  });

  gearLayer?.querySelectorAll<HTMLButtonElement>("[data-gear-detail-sell]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const idx = Number(btn.dataset.gearDetailSell ?? "-1");
      if (!Number.isInteger(idx) || idx < 0 || !save.gearBag?.[idx]) return;
      openGearSellConfirm(idx);
    });
  });
  bindGearSellConfirm();
  bindGearEnhanceConfirm();

  const closeSumMagicDetail = () => {
    sumMagicDetailSlot = null;
    softRefreshSumBookUi({ modals: true });
  };
  magicLayer?.querySelectorAll("#btn-sum-magic-detail-close").forEach((el) => {
    el.addEventListener("click", closeSumMagicDetail);
  });

  magicLayer?.querySelectorAll<HTMLButtonElement>("[data-magic-enhance]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.magicEnhance ?? "";
      if (!id) return;
      if (growthRevealIsOpen()) return;
      const el = activeSummonerElement();
      const kit = getSummonerKit(el);
      const allSkills = Object.values(kit.skills);
      const def = allSkills.find((skill) => skill.id === id);
      if (!def) return;
      const beforeProg = save.summonerMagic?.[el] ?? emptyMagicProgress();
      const beforeRank = magicRank(beforeProg, id);
      const beforeTier2 = magicTier2Unlocked(el, beforeProg);
      const ratePct = Math.round(magicEnhanceSuccessRate(beforeRank) * 100);
      const r = runEnhanceMagicSkill(save, id);
      // Gate failures never spend; only real attempts set enhanceSuccess.
      if (r.enhanceSuccess == null) return;
      save = r.save;
      persist();
      const afterProg = r.save.summonerMagic?.[el] ?? emptyMagicProgress();
      const afterRank = magicRank(afterProg, id);
      if (!r.enhanceSuccess) {
        softRefreshSumBookUi({ skills: true, modals: true });
        beginGrowthReveal({
          kind: "magic",
          portraitHtml: summonerSkillArtImg(def.id, "growth-rite-img", 96),
          name: def.nameKo,
          heroLine: t("ui.growthMagicFail", { pct: ratePct }),
          stats: [],
          skills: [
            {
              name: def.nameKo,
              iconHtml: summonerSkillArtImg(def.id, "growth-skill-img", 44),
              from: beforeRank,
              to: beforeRank,
              effect: t("ui.growthMagicFailNote"),
            },
          ],
          notes: [],
          outcome: "fail",
          ratePct,
        });
        return;
      }
      const notes: string[] = [];
      let unlockedSlots: MagicSkillSlot[] = [];
      if (!beforeProg.branch && afterProg.branch) {
        const next =
          afterProg.branch === "A"
            ? [kit.skills.A1, kit.skills.A2]
            : [kit.skills.B1, kit.skills.B2];
        unlockedSlots =
          afterProg.branch === "A" ? ["A1", "A2"] : ["B1", "B2"];
        notes.push(
          t("ui.growthMagicUnlockBranch", {
            skill1: next[0].nameKo,
            skill2: next[1].nameKo,
          }),
        );
      } else if (!beforeTier2 && magicTier2Unlocked(el, afterProg)) {
        const next =
          afterProg.branch === "A"
            ? [kit.skills.A3, kit.skills.A4]
            : [kit.skills.B3, kit.skills.B4];
        unlockedSlots =
          afterProg.branch === "A" ? ["A3", "A4"] : ["B3", "B4"];
        notes.push(
          t("ui.growthMagicUnlockTier2", {
            skill1: next[0].nameKo,
            skill2: next[1].nameKo,
          }),
        );
      }
      if (unlockedSlots.length) {
        sumMagicJustUnlockedSlots = unlockedSlots;
        if (sumMagicUnlockPulseTimer) window.clearTimeout(sumMagicUnlockPulseTimer);
        sumMagicUnlockPulseTimer = window.setTimeout(() => {
          sumMagicJustUnlockedSlots = [];
          sumMagicUnlockPulseTimer = 0;
          softRefreshSumBookUi({ skills: true });
        }, 1200);
      }
      const afterLines = magicSkillDescLines(def, afterRank);
      softRefreshSumBookUi({ skills: true, modals: true });
      beginGrowthReveal({
        kind: "magic",
        portraitHtml: summonerSkillArtImg(def.id, "growth-rite-img", 96),
        name: def.nameKo,
        heroLine: t("ui.growthMagicRank", { from: beforeRank, to: afterRank }),
        stats: [],
        skills: [
          {
            name: def.nameKo,
            iconHtml: summonerSkillArtImg(def.id, "growth-skill-img", 44),
            from: beforeRank,
            to: afterRank,
            effect: afterLines.slice(1).join(` ${MIDDOT} `) || afterLines[0] || "",
          },
        ],
        notes,
        outcome: "success",
        ratePct,
      });
    });
  });
}

/** Soft-update skill icon selection + detail pane (no full re-render). */
function applyMonSkillPickUi(): boolean {
  const pane = app.querySelector<HTMLElement>("[data-mon-skills-section]");
  if (!pane) return false;
  const owned = selectedEnhanceUid
    ? save.roster.find((m) => m.uid === selectedEnhanceUid)
    : null;
  if (!owned) return false;
  const def = getMonster(owned.monsterId);
  const levels = (owned.skillLevels ?? [1, 1, 1]) as [number, number, number];
  if (monSkillPick < 0 || monSkillPick > 2) monSkillPick = 0;
  const focusSk = def?.skills[monSkillPick];
  const focusLv = levels[monSkillPick] ?? 1;

  pane.querySelectorAll<HTMLButtonElement>("[data-mon-skill-pick]").forEach((btn) => {
    const slot = Number(btn.dataset.monSkillPick ?? "0");
    const on = slot === monSkillPick;
    const lv = levels[slot] ?? 1;
    const maxSk = lv >= MAX_SKILL_LEVEL;
    btn.classList.toggle("is-active", on);
    btn.classList.toggle("is-max", maxSk);
    btn.setAttribute("aria-pressed", on ? "true" : "false");
    const lvEl = btn.querySelector<HTMLElement>(".mon-skill-ico-lv");
    if (lvEl) lvEl.textContent = monSkillLevelBadgeText(lv);
  });

  const main = pane.querySelector<HTMLElement>(".mon-skill-main");
  if (main) {
    main.innerHTML = renderMonsterSkillDetailHtml(focusSk, focusLv);
  }
  dematteArtInTree(pane, "img.mon-skill-ico-img, img.mon-skill-art-img");
  return true;
}

