/** Compact display for wallet amounts in the app bar. */
function fmtRes(n: number): string {
  const v = Math.floor(n);
  if (v >= 1_000_000) return `${(v / 1_000_000).toFixed(1)}M`;
  if (v >= 10_000) return `${(Math.round(v / 100) / 10).toFixed(1)}K`;
  return formatNumber(v);
}

function elementLabel(el: SummonerElement): string {
  return t(`element.${el}`);
}

function languageOptionsHtml(): string {
  const current = getLocale();
  return listLocales()
    .map(
      (loc) =>
        `<option value="${loc.id}" ${loc.id === current ? "selected" : ""}>${escapeHtml(loc.nativeName)}</option>`,
    )
    .join("");
}

function escapeHtml(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

/** Green (+N) / (+N%) suffix for symbol-added combat stats. */
function formatSymbolStatBonusHtml(delta: number, percent: boolean): string {
  if (delta <= 0) return "";
  const body = percent ? `(+${delta}%)` : `(+${delta})`;
  return `<span class="mon-stat-tile-bonus">${body}</span>`;
}

function formatInspectStatValueHtml(
  base: number,
  final: number,
  opts?: { percent?: boolean; combined?: boolean },
): string {
  const percent = Boolean(opts?.percent);
  const main = percent ? `${final}%` : String(final);
  const bonus = opts?.combined
    ? ""
    : formatSymbolStatBonusHtml(final - base, percent);
  return `<span class="mon-stat-tile-num">${main}</span>${bonus}`;
}

function renderInspectCombatStatsHtml(
  preview: NonNullable<ReturnType<typeof previewOwnedCombatStats>>,
  opts?: { combined?: boolean },
): string {
  const { base, final } = preview;
  const combined = Boolean(opts?.combined);
  const core: Array<{ id: string; k: string; v: string }> = [
    { id: "hp", k: t("ui.statHp"), v: formatInspectStatValueHtml(base.hp, final.hp, { combined }) },
    { id: "atk", k: t("ui.statAtk"), v: formatInspectStatValueHtml(base.atk, final.atk, { combined }) },
    { id: "def", k: t("ui.statDef"), v: formatInspectStatValueHtml(base.def, final.def, { combined }) },
    { id: "spd", k: t("ui.statSpd"), v: formatInspectStatValueHtml(base.spd, final.spd, { combined }) },
  ];
  const combat: Array<{ id: string; k: string; v: string }> = [
    {
      id: "cri-rate",
      k: t("ui.statCriRate"),
      v: formatInspectStatValueHtml(base.critRate, final.critRate, {
        percent: true,
        combined,
      }),
    },
    {
      id: "cri-dmg",
      k: t("ui.statCriDmg"),
      v: formatInspectStatValueHtml(base.critDmg, final.critDmg, {
        percent: true,
        combined,
      }),
    },
    {
      id: "acc",
      k: t("ui.statAcc"),
      v: formatInspectStatValueHtml(base.accuracy, final.accuracy, {
        percent: true,
        combined,
      }),
    },
    {
      id: "res",
      k: t("ui.statRes"),
      v: formatInspectStatValueHtml(base.resistance, final.resistance, {
        percent: true,
        combined,
      }),
    },
  ];
  const tile = (row: { id: string; k: string; v: string }, tone: "core" | "combat") =>
    `<div class="mon-stat-tile mon-stat-tile--${tone} mon-stat-tile--${row.id}" role="listitem">
      <span class="mon-stat-tile-k">${escapeHtml(row.k)}</span>
      <span class="mon-stat-tile-v">${row.v}</span>
    </div>`;

  return `<section class="mon-stats-panel" aria-label="${escapeHtml(t("ui.monStatsTitle"))}">
    <div class="mon-stats-grid mon-stats-grid--all" role="list">
      ${core.map((row) => tile(row, "core")).join("")}
      ${combat.map((row) => tile(row, "combat")).join("")}
    </div>
  </section>`;
}

/** Seal-style X close control; triggers the matching backdrop close button. */
function modalCloseX(ariaLabel: string, closeBtnId: string): string {
  return `<button type="button" class="modal-x" data-modal-x-for="${closeBtnId}" aria-label="${escapeHtml(ariaLabel)}"></button>`;
}

/** Drop the rest of this tap so replacing a button cannot activate the new control. */
function eatTrailingTap(ms = 400): void {
  let done = false;
  const release = (): void => {
    if (done) return;
    done = true;
    document.removeEventListener("click", swallow, true);
    document.removeEventListener("pointerup", swallow, true);
  };
  function swallow(e: Event): void {
    if (!e.isTrusted) return;
    e.preventDefault();
    e.stopImmediatePropagation();
    release();
  }
  document.addEventListener("click", swallow, true);
  document.addEventListener("pointerup", swallow, true);
  window.setTimeout(release, ms);
}

/** One-time capture delegate so soft-injected modals (chat, drop-info, …) keep a working X. */
let modalXDelegateBound = false;
function ensureModalXDelegate(): void {
  if (modalXDelegateBound) return;
  modalXDelegateBound = true;
  app.addEventListener(
    "click",
    (ev) => {
      const t = ev.target;
      if (!(t instanceof Element)) return;
      const btn = t.closest<HTMLButtonElement>("[data-modal-x-for]");
      if (!btn || !app.contains(btn)) return;
      ev.preventDefault();
      ev.stopPropagation();
      const id = btn.dataset.modalXFor;
      if (!id) return;
      const closeBtn = app.querySelector<HTMLButtonElement>(`#${CSS.escape(id)}`);
      if (!closeBtn) return;
      eatTrailingTap();
      closeBtn.click();
    },
    true,
  );
}

function sysConfirmTitle(kind: "login" | "exit"): string {
  return kind === "exit" ? t("nav.exitGame") : t("nav.confirmLogin");
}

function renderSysConfirmLayer(): string {
  const kind = sysConfirmKind;
  const open = !!kind;
  const title = kind ? sysConfirmTitle(kind) : "";
  const cancel = escapeHtml(t("ui.19b2d19bc1"));
  return `<div class="settings-layer sys-confirm-layer" id="sys-confirm-layer" ${open ? "" : "hidden"} aria-hidden="${open ? "false" : "true"}">
    <button type="button" class="settings-backdrop" id="btn-sys-confirm-backdrop" aria-label="${cancel}"></button>
    <div class="gear-sell-confirm-sheet sys-confirm-sheet" role="dialog" aria-modal="true" aria-labelledby="sys-confirm-title">
      ${modalCloseX(t("ui.19b2d19bc1"), "btn-sys-confirm-backdrop")}
      <h2 class="gear-sell-confirm-title" id="sys-confirm-title">${escapeHtml(title)}</h2>
      <div class="gear-sell-acts">
        <button type="button" class="secondary" id="btn-sys-confirm-cancel">${cancel}</button>
        <button type="button" class="auth-btn-primary" id="btn-sys-confirm-ok">${escapeHtml(t("ui.468266d639"))}</button>
      </div>
    </div>
  </div>`;
}

function applySysConfirmOpen(): void {
  let layer = app.querySelector<HTMLElement>("#sys-confirm-layer");
  if (!layer) {
    if (!sysConfirmKind) {
      rememberOverlayClose("sys-confirm-layer");
      return;
    }
    app.insertAdjacentHTML("beforeend", renderSysConfirmLayer());
    layer = app.querySelector<HTMLElement>("#sys-confirm-layer");
  }
  if (!layer) return;
  const titleEl = layer.querySelector("#sys-confirm-title");
  if (titleEl) titleEl.textContent = sysConfirmKind ? sysConfirmTitle(sysConfirmKind) : "";
  layer.hidden = !sysConfirmKind;
  layer.setAttribute("aria-hidden", sysConfirmKind ? "false" : "true");
  if (sysConfirmKind) {
    promoteOverlayToAppRoot(layer);
    replayModalPop(layer);
  } else {
    rememberOverlayClose("sys-confirm-layer");
  }
}

function closeSysConfirm(): void {
  if (!sysConfirmKind) return;
  sysConfirmKind = null;
  applySysConfirmOpen();
}

function openSysConfirm(kind: "login" | "exit"): void {
  sysConfirmKind = kind;
  applySysConfirmOpen();
  ensureSysConfirmDelegate();
}

function confirmSysConfirm(): void {
  const kind = sysConfirmKind;
  closeSysConfirm();
  if (kind === "exit") {
    void exitNativeApp();
    return;
  }
  if (kind === "login") returnToLoginScreen();
}

let sysConfirmDelegateBound = false;
function ensureSysConfirmDelegate(): void {
  if (sysConfirmDelegateBound) return;
  sysConfirmDelegateBound = true;
  app.addEventListener("click", (ev) => {
    const t = ev.target;
    if (!(t instanceof Element)) return;
    if (t.closest("#btn-sys-confirm-ok")) {
      ev.preventDefault();
      confirmSysConfirm();
      return;
    }
    if (t.closest("#btn-sys-confirm-cancel, #btn-sys-confirm-backdrop")) {
      ev.preventDefault();
      closeSysConfirm();
    }
  });
}

function returnToLoginScreen(): void {
  persist();
  stopChatLive();
  chatOpen = false;
  profileOpen = false;
  settingsOpen = false;
  mailboxOpen = false;
  notifOpen = false;
  missionOpen = false;
  communityOpen = false;
  shopOpen = false;
  resMoreOpen = false;
  summonerPickerOpen = false;
  battle = null;
  currentStage = null;
  autoMode = false;
  clearAutoTimer();
  authUi.pane = "gate";
  overlayBackStack = [];
  viewHistory = [];
  viewHistoryLock = true;
  sysConfirmKind = null;
  view = "auth";
  lastTrackedView = "auth";
  render();
  viewHistoryLock = false;
}

function adoptSessionNickname(user: SessionUser): void {
  const nick = user.nickname?.trim();
  if (!nick) return;
  if ((save.profileNickname ?? "").trim()) return;
  save = { ...save, profileNickname: nick };
  persist();
}

/** Short display name for profile overlays. */
function storedProfileNickname(): string {
  if (!sessionUser) return "";
  const fromSave = save.profileNickname?.trim();
  if (fromSave) return fromSave;
  const fromSession = sessionUser.nickname?.trim();
  if (fromSession) return fromSession;
  return "";
}

function hasValidProfileNickname(): boolean {
  return validateNickname(storedProfileNickname()).ok;
}

function needsNicknameSetup(): boolean {
  if (!sessionUser) return false;
  if (sessionUser.kind === "demo") return false;
  return !hasValidProfileNickname();
}

function needsStarterSummonerPick(): boolean {
  if (!sessionUser) return false;
  if (sessionUser.kind === "demo") return false;
  return save.starterSummonerPicked !== true;
}

function summonerLockNeedLv(el: SummonerElement): number | null {
  if (isSummonerUnlocked(save, el)) return null;
  if (canUnlockAdditionalSummoner(save, el)) return null;
  return nextSummonerUnlockLevel(unlockedSummonerList(save).length);
}

function isSummonerSlotLocked(el: SummonerElement): boolean {
  return !isSummonerUnlocked(save, el) && !canUnlockAdditionalSummoner(save, el);
}

function summonerSlotClass(el: SummonerElement, extra = ""): string {
  const unlocked = isSummonerUnlocked(save, el);
  const unlockable = !unlocked && canUnlockAdditionalSummoner(save, el);
  const bits = [extra];
  if (!unlocked) bits.push("is-locked");
  if (unlockable) bits.push("is-unlockable");
  return bits.filter(Boolean).join(" ");
}

function summonerLockBadgeHtml(el: SummonerElement): string {
  if (isSummonerUnlocked(save, el)) return "";
  if (canUnlockAdditionalSummoner(save, el)) {
    return `<span class="summoner-lock-badge is-unlockable">${CODEX_LOCK_HTML}<strong>${escapeHtml(t("summonerPicker.unlock"))}</strong></span>`;
  }
  const need = summonerLockNeedLv(el);
  if (need == null) return "";
  return `<span class="summoner-lock-badge">${CODEX_LOCK_HTML}<strong>${escapeHtml(t("summonerPicker.needLv", { n: need }))}</strong></span>`;
}

function renderSummonerInfoLockFooter(el: SummonerElement): string {
  if (isSummonerUnlocked(save, el)) return "";
  if (canUnlockAdditionalSummoner(save, el)) {
    return `<button type="button" class="auth-btn-primary summoner-info-unlock" id="btn-summoner-info-unlock">${escapeHtml(t("ui.summonerUnlock.confirm"))}</button>`;
  }
  const need = summonerLockNeedLv(el);
  if (need == null) return "";
  return `<p class="summoner-info-lock">${escapeHtml(t("ui.summonerInfo.unlockAt", { n: need }))}</p>`;
}

function renderSummonerInfoBody(el: SummonerElement): string {
  const p = save.summoners?.[el] ?? { level: 1, exp: 0, awaken: 0 };
  const kit = getSummonerKit(el);
  const leader = kit.leader;
  const prog = save.summonerMagic?.[el] ?? emptyMagicProgress();
  const unlocked = unlockedMagicSkills(el, prog);
  const leaderBits = stagePrepLeaderPassive({
    ...save,
    activeSummoner: el,
  });
  const leaderBuffs = renderLeaderBuffChips(leader, el);
  const skillRow = unlocked
    .map((sk) => {
      const rank = magicRank(prog, sk.id);
      return `<div class="stage-prep-info-skill">
        ${summonerSkillArtImg(sk.id, "stage-prep-info-skill-img", 36)}
        <span class="stage-prep-info-skill-copy">
          <strong>${escapeHtml(sk.nameKo)}</strong>
          <small>${escapeHtml(
            t("ui.magicRankLabel", { rank, max: MAX_MAGIC_RANK }),
          )}</small>
        </span>
      </div>`;
    })
    .join("");
  const locked = !isSummonerUnlocked(save, el);
  const levelLine = locked
    ? escapeHtml(elementLabel(el))
    : `${escapeHtml(elementLabel(el))} ${MIDDOT} Lv.${accountLevelOf(save)} ${summonerAwakenGemsHtml(p.awaken, "sum-awaken-gems-wrap--inline")}`;
  return `<div class="summoner-info-body">
    <div class="stage-prep-info-hero el-${el}">
      <img class="stage-prep-info-art" src="${summonerArtSrc(el)}" width="88" height="88" alt="" draggable="false" decoding="async" />
      <div class="stage-prep-info-hero-copy">
        <strong>${escapeHtml(leader.nameKo)}</strong>
        <small>${levelLine}</small>
        <p class="stage-prep-info-leader"><span>${escapeHtml(t("ui.stagePrepLeaderPassive"))}</span></p>
        <div class="stage-prep-leader-markers">${renderLeaderPassiveMarkerChips(leaderBits.markers)}</div>
      </div>
    </div>
    <div class="stage-prep-info-section">
      <h3>${escapeHtml(t("ui.sumBookLeader"))}</h3>
      <div class="sum-leader-buffs">${leaderBuffs}</div>
    </div>
    <div class="stage-prep-info-section">
      <h3>${escapeHtml(t("ui.stagePrepInfoSkills"))}</h3>
      <div class="stage-prep-info-skills">${skillRow || `<p class="muted">${escapeHtml(t("ui.stagePrepSkillLocked"))}</p>`}</div>
    </div>
    ${renderSummonerInfoLockFooter(el)}
  </div>`;
}

function renderSummonerInfoLayer(): string {
  const el = summonerInfoEl;
  const open = summonerInfoOpen && el != null;
  const body = open ? renderSummonerInfoBody(el) : "";
  const title = open
    ? escapeHtml(getSummonerKit(el).leader.nameKo)
    : escapeHtml(t("ui.summonerInfo.title"));
  return `<div class="settings-layer" id="summoner-info-layer" ${open ? "" : "hidden"} aria-hidden="${open ? "false" : "true"}">
    <button type="button" class="settings-backdrop" id="btn-summoner-info-close" aria-label="${escapeHtml(t("ui.summonerInfo.close"))}"></button>
    <div class="settings-sheet summoner-info-sheet" role="dialog" aria-modal="true" aria-labelledby="summoner-info-title">
      ${modalCloseX(t("ui.summonerInfo.close"), "btn-summoner-info-close")}
      <h2 class="settings-title" id="summoner-info-title">${title}</h2>
      <div id="summoner-info-body-host">${body}</div>
    </div>
  </div>`;
}

function applySummonerInfoOpen(): void {
  const layer = app.querySelector<HTMLElement>("#summoner-info-layer");
  const open = summonerInfoOpen && summonerInfoEl != null;
  if (!layer) {
    if (open) render();
    return;
  }
  layer.hidden = !open;
  layer.setAttribute("aria-hidden", open ? "false" : "true");
  if (!open) {
    cueModalSfx("summoner-info", false);
    return;
  }
  const el = summonerInfoEl!;
  const title = layer.querySelector<HTMLElement>("#summoner-info-title");
  if (title) title.textContent = getSummonerKit(el).leader.nameKo;
  const bodyHost = layer.querySelector<HTMLElement>("#summoner-info-body-host");
  if (bodyHost) bodyHost.innerHTML = renderSummonerInfoBody(el);
  promoteOverlayToAppRoot(layer);
  replayModalPop(layer);
  bindSummonerInfoUi();
  cueModalSfx("summoner-info", true);
}

function closeSummonerInfoSoft(): void {
  if (!summonerInfoOpen) return;
  summonerInfoOpen = false;
  summonerInfoEl = null;
  applySummonerInfoOpen();
}

function openSummonerInfoSoft(el: SummonerElement): void {
  summonerInfoEl = el;
  summonerInfoOpen = true;
  if (!app.querySelector("#summoner-info-layer")) {
    render();
    return;
  }
  applySummonerInfoOpen();
}

function confirmSummonerUnlock(el: SummonerElement): void {
  if (!canUnlockAdditionalSummoner(save, el)) return;
  const r = unlockAdditionalSummoner(save, el);
  save = setActiveSummoner(r.save, el);
  persist();
  if (hasSpareSummonerUnlockSlot(save)) {
    summonerUnlockPromptedCount = unlockedSummonerList(save).length;
  }
  closeSummonerInfoSoft();
  stagePrepInfo = null;
  applyStagePrepInfo();
  if (view === "stages" && stageEntryId) applyStagesRegionOpen({ animate: false });
  else if (view === "party") applyPartyHallOpen({ animate: false });
  else render();
  maybeOfferSummonerUnlock();
}

function bindSummonerInfoUi(): void {
  const layer = app.querySelector("#summoner-info-layer");
  if (!layer) return;
  const close = () => closeSummonerInfoSoft();
  const closeBtn = layer.querySelector<HTMLButtonElement>("#btn-summoner-info-close");
  if (closeBtn) closeBtn.onclick = close;
  const backdrop = layer.querySelector<HTMLButtonElement>(".settings-backdrop");
  if (backdrop) backdrop.onclick = close;
  const unlockBtn = layer.querySelector<HTMLButtonElement>("#btn-summoner-info-unlock");
  if (unlockBtn) {
    unlockBtn.onclick = () => {
      const el = summonerInfoEl;
      if (!el) return;
      confirmSummonerUnlock(el);
    };
  }
}

function tapSummonerSlot(
  el: SummonerElement,
  opts?: { closePicker?: boolean },
): boolean {
  if (!isSummonerUnlocked(save, el)) {
    openSummonerInfoSoft(el);
    return false;
  }
  if (el === (save.activeSummoner ?? "light")) return false;
  save = setActiveSummoner(save, el);
  persist();
  flash(t("summonerPicker.switched", { element: elementLabel(el) }));
  if (opts?.closePicker) {
    summonerPickerOpen = false;
    applySummonerPickerOpen();
  }
  return true;
}

function activateOrUnlockSummoner(el: SummonerElement): boolean {
  if (el === (save.activeSummoner ?? "light") && isSummonerUnlocked(save, el)) {
    return false;
  }
  if (!isSummonerUnlocked(save, el)) {
    if (!canUnlockAdditionalSummoner(save, el)) {
      return false;
    }
    const r = unlockAdditionalSummoner(save, el);
    save = setActiveSummoner(r.save, el);
    persist();
    flash(t("summonerPicker.unlocked", { element: elementLabel(el) }));
    if (hasSpareSummonerUnlockSlot(save)) {
      summonerUnlockPromptedCount = unlockedSummonerList(save).length;
    }
    return true;
  }
  save = setActiveSummoner(save, el);
  persist();
  flash(t("summonerPicker.switched", { element: elementLabel(el) }));
  return true;
}

function loadPartyPresetUi(idx: number): boolean {
  const presets = normalizePartyPresets(save, save.partyPresets);
  const preset = presets[idx];
  if (preset && !isSummonerUnlocked(save, preset.summoner)) {
    const need = nextSummonerUnlockLevel(unlockedSummonerList(save).length);
    if (need != null) flash(t("summonerPicker.needLv", { n: need }));
    return false;
  }
  const r = runLoadPartyPreset(save, idx);
  save = r.save;
  partyDraft = new Set(save.party);
  persist();
  flash(t("ui.stagePrepDeckLoaded", { n: idx + 1 }));
  return true;
}

function displayNickname(): string {
  const stored = storedProfileNickname();
  if (stored) return stored;
  const email = sessionUser?.email?.trim();
  if (email) {
    const local = email.split("@")[0] || email;
    return local.length > 10 ? `${local.slice(0, 10)}?` : local;
  }
  if (sessionUser?.kind === "demo") return t("account.demo");
  if (sessionUser?.kind === "guest") return t("account.guest");
  return t("account.default");
}

/** Toggle currency drawer without a full screen re-render. */
function applyResMoreOpen(): void {
  const btn = app.querySelector<HTMLButtonElement>("#btn-res-more");
  const panel = app.querySelector<HTMLElement>("#res-more-panel");
  if (btn) {
    btn.classList.toggle("is-open", resMoreOpen);
    btn.setAttribute("aria-expanded", resMoreOpen ? "true" : "false");
    const label = resMoreOpen ? t("res.moreClose") : t("res.moreOpen");
    btn.title = label;
    btn.setAttribute("aria-label", label);
  }
  if (panel) {
    panel.classList.toggle("is-open", resMoreOpen);
    if (resMoreOpen) panel.removeAttribute("hidden");
    else panel.setAttribute("hidden", "");
  }
  cueModalSfx("res-more", resMoreOpen);
  if (resMoreOpen) rememberOverlayOpen("res-more");
  else rememberOverlayClose("res-more");
}


/** Replay centered modal pop animation when a layer becomes visible. */
function replayModalPop(layer: HTMLElement | null): void {
  const sheet = layer?.querySelector<HTMLElement>(
    ".settings-sheet, .mission-sheet, .mission-reward-sheet, .community-sheet, .shop-sheet, .stages-region-sheet, .stage-entry-modal, .skill-feed-sheet, .power-up-sheet, .building-info-sheet, .feature-unlock-sheet, .attendance-sheet, .summoner-info-sheet, .bldg-up-sheet, .dojo-insc-up-sheet, .sym-detail-compare, .sym-detail-sheet, .sym-bag-expand-sheet, .codex-sheet, .forge-reveal, .gear-detail-compare, .gear-detail-sheet, .gear-sell-confirm-sheet, .sys-confirm-sheet, .sum-magic-detail-sheet, .battle-auto-settings-card, .stone-result-sheet, .stone-pick-help-sheet, .battle-skill-info-sheet, .growth-result-sheet, .growth-rite-play, .glory-up-play",
  );
  if (!sheet) return;
  sheet.style.animation = "none";
  void sheet.offsetWidth;
  sheet.style.animation = "";
}

/**
 * Soft UI rule: overlays must never remount hub-sky / the whole screen.
 * Prefer host patch, always-mounted `hidden` layers, or inject/remove one overlay node.
 */
function softPatchHost(hostSelector: string, html: string): HTMLElement | null {
  const host = app.querySelector<HTMLElement>(hostSelector);
  if (!host) return null;
  host.innerHTML = html;
  return host;
}

/** Last-opened overlay sits above HUD / tabs / earlier sheets. */
let overlayStackZ = 10000;
/** Skip back-stack bookkeeping while re-porting known layers after a render. */
let overlayPromoteQuiet = false;
/** Overlay ids in open order (most recent last) for hardware back. */
let overlayBackStack: string[] = [];
/** Previous game screens for hardware back (most recent last). */
let viewHistory: View[] = [];
let viewHistoryLock = false;
let lastTrackedView: View = view;

function rememberOverlayOpen(id: string): void {
  if (!id) return;
  overlayBackStack = overlayBackStack.filter((item) => item !== id);
  overlayBackStack.push(id);
  applyGuideRailOpen();
}

function rememberOverlayClose(id: string): void {
  if (!id) return;
  overlayBackStack = overlayBackStack.filter((item) => item !== id);
  applyGuideRailOpen();
}

function overlayDomIsOpen(el: HTMLElement): boolean {
  if (el.id === "facility-layer") return false;
  if (el.hidden) return false;
  if (el.getAttribute("aria-hidden") === "true") return false;
  return true;
}

/** Move a modal layer to `#app` so it escapes `main` / facility stacking contexts. */
function promoteOverlayToAppRoot(el: Element | null | undefined): HTMLElement | null {
  if (!(el instanceof HTMLElement)) return null;
  overlayStackZ += 1;
  el.classList.add("is-ported");
  el.style.position = "fixed";
  el.style.inset = "0";
  el.style.zIndex = String(overlayStackZ);
  app.appendChild(el);
  if (!overlayPromoteQuiet && el.id && overlayDomIsOpen(el)) {
    rememberOverlayOpen(el.id);
  }
  return el;
}

