function syncMissionNavBadge(): void {
  const btn = app.querySelector("#btn-mission");
  if (!btn) return;
  const n = claimableDailyMissionCount(save) + claimableMainQuestCount(save);
  const existing = btn.querySelector(".tab-badge");
  if (n <= 0) {
    existing?.remove();
    return;
  }
  const label = t("mission.badge", { n });
  if (existing) {
    existing.textContent = String(n);
    existing.setAttribute("aria-label", label);
    return;
  }
  btn
    .querySelector(".seal-badge")
    ?.insertAdjacentHTML(
      "beforeend",
      `<span class="tab-badge" aria-label="${escapeHtml(label)}">${n}</span>`,
    );
}

function syncHudAfterMissionClaim(): void {
  syncHudResources();
  syncEnergyHud();
  const jinmun = app.querySelector<HTMLElement>(".res-item--jinmun .res-val");
  if (jinmun) jinmun.textContent = fmtRes(save.jinmunStones ?? 0);
  app.querySelectorAll<HTMLElement>(".res-item--scroll").forEach((item) => {
    const title = item.getAttribute("title") ?? "";
    const val = item.querySelector<HTMLElement>(".res-val");
    if (!val) return;
    if (title === t("res.scrollNormal")) val.textContent = fmtRes(scrollCount(save, "normal"));
    if (title === t("res.scrollPremium")) val.textContent = fmtRes(scrollCount(save, "premium"));
    if (title === t("res.scrollMystic")) val.textContent = fmtRes(scrollCount(save, "mystic"));
  });
  syncMissionNavBadge();
}

function goFromMission(nav: string): void {
  missionOpen = false;
  applyMissionOpen();
  if (nav === "guild") {
    openCommunityModalSoft();
    return;
  }
  if (nav === "shop") {
    openShopModalSoft();
    return;
  }
  communityOpen = false;
  shopOpen = false;
  applyCommunityOpen();
  applyShopOpen();
  if (nav === "enhance:symbols") {
    enhanceTab = "monsters";
    monBookDock = "symbols";
    const next = "enhance" as View;
    const stayOnIsland =
      (view === "home" || isFacilityView(view)) &&
      Boolean(app.querySelector(".home-island"));
    view = next;
    if (stayOnIsland) renderPreservingIsland();
    else render();
    return;
  }
  if (nav.startsWith("stages:")) {
    const region = nav.slice("stages:".length) as StagesRegionId;
    const stay = view === "stages";
    view = "stages";
    stagesRegion = region;
    stageEntryId = null;
    if (stay) {
      applyStagesRegionOpen();
      focusStagesRegion(region);
      return;
    }
    render();
    return;
  }
  const next = nav as View;
  const stayOnIsland =
    (view === "home" || isFacilityView(view)) &&
    (next === "home" || isFacilityView(next)) &&
    Boolean(app.querySelector(".home-island"));
  view = next;
  if (stayOnIsland) renderPreservingIsland();
  else render();
}

