function renderFusionBodyHtml(): string {
  const lv = save.island.summonerLevel;
  const fusionStarOk =
    lv >= 17 || save.island.buildings.some((b) => b.id === "fusion_star");

  if (fusionPanel === "pair") {
    const pairs: string[] = [];
    if (fusionStarOk) {
      for (let i = 0; i < save.roster.length; i++) {
        for (let j = i + 1; j < save.roster.length; j++) {
          if (save.roster[i]!.monsterId === save.roster[j]!.monsterId) {
            pairs.push(`${i}:${j}`);
          }
        }
      }
    }
    const pairRows = !fusionStarOk
      ? `<p class="fusion-empty muted">${escapeHtml(t("ui.fusion.sameSpeciesLocked"))}</p>`
      : pairs.length
        ? pairs
            .map((p) => {
              const [a, b] = p.split(":");
              const ma = save.roster[Number(a)]!;
              const mb = save.roster[Number(b)]!;
              const evo = Math.min(
                MAX_EVOLVE,
                Math.max(ma.evolve ?? 0, mb.evolve ?? 0) + 1,
              );
              return `<button type="button" class="fusion-pair" data-fuse-a="${a}" data-fuse-b="${b}">
                <span class="fusion-pair-arts" aria-hidden="true">
                  <span class="fusion-pair-art">${ownedMonsterArtImg(ma, "fusion-pair-img", 48)}</span>
                  <span class="fusion-flow-op">+</span>
                  <span class="fusion-pair-art">${ownedMonsterArtImg(mb, "fusion-pair-img", 48)}</span>
                </span>
                <span class="fusion-pair-body">
                  <strong>${escapeHtml(describeOwned(ma))} + ${escapeHtml(describeOwned(mb))}</strong>
                  <small>${escapeHtml(t("ui.ebc3c5c656"))} ${evo}</small>
                </span>
                <span class="fusion-pair-side">
                  ${shopPriceMana(FUSION_MANA_COST)}
                  <span class="fusion-recipe-cta">${escapeHtml(t("ui.fusion.fuseCta"))}</span>
                </span>
              </button>`;
            })
            .join("")
        : `<p class="fusion-empty muted">${escapeHtml(t("ui.fusion.pairEmpty"))}</p>`;

    return `<section class="fusion-altar" aria-labelledby="fusion-altar-title">
      <div class="fusion-altar-stage">
        <div class="fusion-altar-aura" aria-hidden="true"></div>
        <img class="fusion-altar-circle" src="/art/hub/forge-circle.webp" width="240" height="240" alt="" draggable="false" onerror="this.onerror=null;this.src='/art/hub/forge-circle.svg'" />
        <img class="fusion-altar-bldg" src="/art/hub/bldg-fusion.webp" width="360" height="220" alt="" draggable="false" onerror="this.onerror=null;this.src='/art/hub/emblem-fusion.svg'" />
        <div class="fusion-altar-veil" aria-hidden="true"></div>
        <h2 class="fusion-altar-title" id="fusion-altar-title">${escapeHtml(t("ui.hubFusion"))}</h2>
        <p class="fusion-altar-lead">${escapeHtml(t("ui.fusion.pairAltarLead"))}</p>
      </div>
    </section>
    <section class="fusion-block fusion-block--pair" aria-labelledby="fusion-pair-title">
      <header class="fusion-block-head">
        <span class="fusion-block-seal fusion-block-seal--pair" aria-hidden="true">${Mark.dual}</span>
        <div class="fusion-block-copy">
          <h2 class="fusion-block-title" id="fusion-pair-title">${escapeHtml(t("ui.fusion.sameSpecies"))}</h2>
        </div>
      </header>
      <div class="fusion-pair-list">${pairRows}</div>
    </section>`;
  }

  const recipeRows = FUSION_RECIPES.map((recipe) => {
    const result = getMonster(recipe.resultMonsterId);
    const plan = planFusionRecipe(save.roster, recipe);
    const needLv = recipe.unlockSummonerLevel ?? 1;
    const lockedLv = lv < needLv;
    const cost = recipe.manaCost ?? FUSION_MANA_COST;
    const ready = plan.ok && !lockedLv && save.island.mana >= cost;
    const mats = plan.counts
      .map((c, idx) => {
        const def = getMonster(c.monsterId);
        const filled = c.have >= c.need;
        const plus =
          idx > 0
            ? `<span class="fusion-flow-op" aria-hidden="true">+</span>`
            : "";
        return `${plus}<span class="fusion-recipe-mat${filled ? " is-ready" : ""}"${monsterSlotFamilyAttr(c.monsterId)} title="${escapeHtml(def?.nameKo ?? c.monsterId)}">
          <span class="fusion-recipe-mat-frame">${monsterArtImg(c.monsterId, "fusion-recipe-mat-img", 44)}</span>
          <em>${c.have}/${c.need}</em>
        </span>`;
      })
      .join("");
    const status = lockedLv
      ? `<span class="fusion-recipe-status is-warn">${escapeHtml(t("ui.fusion.lockedLv", { n: needLv }))}</span>`
      : !plan.ok
        ? `<span class="fusion-recipe-status is-warn">${escapeHtml(t("ui.fusion.recipeNeed"))}</span>`
        : `<span class="fusion-recipe-status is-ready">${escapeHtml(t("ui.fusion.ready"))}</span>`;
    const exclusive = recipe.fusionOnly
      ? `<span class="fusion-recipe-tag">${escapeHtml(t("ui.fusion.exclusive"))}</span>`
      : "";
    const stars = monStarsHtml(Math.max(1, result?.naturalStars ?? 1));
    return `<button type="button" class="fusion-recipe${ready ? " is-ready" : " is-locked"}" data-recipe-id="${recipe.id}" data-recipe-fodder="${plan.fodderUids.join(",")}" ${ready ? "" : "disabled"}>
      <span class="fusion-recipe-top">
        <span class="fusion-recipe-result">
          <span class="fusion-recipe-result-ring" aria-hidden="true">
            ${monsterArtImg(recipe.resultMonsterId, "fusion-recipe-result-img", 72)}
          </span>
          <span class="fusion-recipe-copy">
            <strong>${escapeHtml(result?.nameKo ?? recipe.resultMonsterId)}</strong>
            <span class="fusion-recipe-stars">${stars}</span>
            <small>${escapeHtml(recipe.nameKo)}</small>
            ${exclusive}
          </span>
        </span>
        <span class="fusion-recipe-side">
          ${shopPriceMana(cost)}
          <span class="fusion-recipe-cta">${escapeHtml(t("ui.fusion.fuseCta"))}</span>
        </span>
      </span>
      <span class="fusion-recipe-flow" aria-hidden="true">
        <span class="fusion-recipe-mats">${mats}</span>
        <span class="fusion-flow-op fusion-flow-op--arrow">${ARROW_RIGHT}</span>
        <span class="fusion-flow-result">${monsterArtImg(recipe.resultMonsterId, "fusion-flow-result-img", 40)}</span>
      </span>
      ${status}
    </button>`;
  }).join("");

  return `<section class="fusion-altar" aria-labelledby="fusion-altar-title">
      <div class="fusion-altar-stage">
        <div class="fusion-altar-aura" aria-hidden="true"></div>
        <img class="fusion-altar-circle" src="/art/hub/forge-circle.webp" width="240" height="240" alt="" draggable="false" onerror="this.onerror=null;this.src='/art/hub/forge-circle.svg'" />
        <img class="fusion-altar-bldg" src="/art/hub/bldg-fusion.webp" width="360" height="220" alt="" draggable="false" onerror="this.onerror=null;this.src='/art/hub/emblem-fusion.svg'" />
        <div class="fusion-altar-veil" aria-hidden="true"></div>
        <h2 class="fusion-altar-title" id="fusion-altar-title">${escapeHtml(t("ui.hubCombine"))}</h2>
        <p class="fusion-altar-lead">${escapeHtml(t("ui.fusion.altarLead"))}</p>
      </div>
    </section>
    <section class="fusion-block" aria-labelledby="fusion-recipes-title">
      <header class="fusion-block-head">
        <span class="fusion-block-seal" aria-hidden="true">${Mark.fusion}</span>
        <div class="fusion-block-copy">
          <h2 class="fusion-block-title" id="fusion-recipes-title">${escapeHtml(t("ui.fusion.recipes"))}</h2>
          <p class="fusion-block-lead">${escapeHtml(t("ui.fusion.hint"))}</p>
        </div>
      </header>
      <div class="fusion-recipe-list">${recipeRows}</div>
    </section>`;
}

function refreshFusionSoft(): boolean {
  const host = app.querySelector<HTMLElement>("#fusion-body-host");
  if (!host) return false;
  host.innerHTML = renderFusionBodyHtml();
  dematteArtInTree(host);
  const mana = app.querySelector<HTMLElement>("#fusion-mana-count");
  if (mana) mana.textContent = fmtRes(save.island.mana);
  syncHudResources();
  return true;
}

function refreshDojoSoft(): boolean {
  const host = app.querySelector<HTMLElement>("#dojo-body-host");
  if (!host) return false;
  const next = document.createElement("div");
  next.innerHTML = renderDojo();
  const sheet = next.firstElementChild;
  if (!sheet) return false;
  host.replaceWith(sheet);
  dematteArtInTree(sheet);
  const jinmun = app.querySelector<HTMLElement>("#dojo-jinmun-count");
  if (jinmun) jinmun.textContent = fmtRes(save.jinmunStones ?? 0);
  syncHudResources();
  return true;
}

function refreshGlorySoft(): boolean {
  const host = app.querySelector<HTMLElement>("#glory-body-host");
  if (!host) return false;
  const next = document.createElement("div");
  next.innerHTML = renderGlory();
  const sheet = next.firstElementChild;
  if (!sheet) return false;
  host.replaceWith(sheet);
  dematteArtInTree(sheet);
  const points = app.querySelector<HTMLElement>("#glory-points-count");
  if (points) points.textContent = fmtRes(save.gloryPoints ?? 0);
  syncHudResources();
  return true;
}

function bindFusionActions(): void {
  app.querySelectorAll<HTMLButtonElement>("[data-fuse-a]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (growthRevealIsOpen()) return;
      const a = save.roster[Number(btn.dataset.fuseA!)];
      const keepUid = a?.uid;
      if (!a || !keepUid) return;
      const beforeSave = save;
      const beforeCount = save.roster.length;
      const r = runFusion(save, btn.dataset.fuseA!, btn.dataset.fuseB!);
      const after = r.save.roster.find((monster) => monster.uid === keepUid);
      const grew = r.save.roster.length < beforeCount && !!after;
      save = r.save;
      persist();
      if (!grew || !after) {
        flash(r.message);
        return;
      }
      beginGrowthReveal(
        buildOwnedGrowthPayload({
          kind: "fusion",
          before: a,
          after,
          beforeSave,
          afterSave: r.save,
        }),
      );
    });
  });

  app.querySelectorAll<HTMLButtonElement>("[data-recipe-id]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (growthRevealIsOpen()) return;
      const recipeId = btn.dataset.recipeId!;
      const fodder = (btn.dataset.recipeFodder ?? "")
        .split(",")
        .filter(Boolean);
      const before = fodder
        .map((uid) => save.roster.find((monster) => monster.uid === uid))
        .find(Boolean);
      const beforeSave = save;
      const r = runRecipeFusion(save, recipeId, fodder);
      const after = r.fusedUid
        ? r.save.roster.find((monster) => monster.uid === r.fusedUid)
        : undefined;
      save = r.save;
      persist();
      if (!before || !after) {
        flash(r.message);
        return;
      }
      beginGrowthReveal(
        buildOwnedGrowthPayload({
          kind: "fusion",
          before,
          after,
          beforeSave,
          afterSave: r.save,
        }),
      );
    });
  });
}

function bindDojoActions(): void {
  app.querySelector("#btn-dojo-drill")?.addEventListener("click", () => {
    const r = runPracticeDojo(save);
    save = r.save;
    persist();
    flash(r.message);
    enqueueBuildingUnlocks(r.unlockedBuildingIds);
    if (!refreshDojoSoft()) render();
    else bindDojoActions();
    showNextBuildingUnlockModal();
  });
  app.querySelectorAll<HTMLButtonElement>("[data-circle-insc]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.circleInsc as CircleInscriptionId;
      openDojoInscUpgradeSoft(id);
    });
  });
}

function bindGloryActions(): void {
  app.querySelectorAll<HTMLButtonElement>("[data-glory]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.glory as GloryBuildingId;
      openGloryUpgradeSoft(id);
    });
  });
}

function renderFusion(): string {
  return `<div class="fusion-sheet">
    <div id="fusion-reveal-host">${renderFusionReveal()}</div>
    <div id="fusion-body-host">${renderFusionBodyHtml()}</div>
  </div>`;
}

const STAGE_DIFFICULTIES: {
  id: StageDifficulty;
  labelKo: string;
  blurb: string;
  energyMul: number;
}[] = [
  {
    id: "normal",
    labelKo: t("ui.aef1a1e70e"),
    blurb: t("ui.2387a8e0b0"),
    energyMul: SCENARIO_DIFF_ENERGY_MUL.normal,
  },
  {
    id: "hard",
    labelKo: t("ui.3dfdef02ab"),
    blurb: t("ui.7be5aa7542"),
    energyMul: SCENARIO_DIFF_ENERGY_MUL.hard,
  },
  {
    id: "hell",
    labelKo: t("ui.173366486b"),
    blurb: t("ui.ab309da205"),
    energyMul: SCENARIO_DIFF_ENERGY_MUL.hell,
  },
];

function stageEnergyCost(stage: StageDef): number {
  return Math.max(0, energyCostForStage(stage, effectiveDiff(stage)));
}

function stageDropSlots(stage: StageDef): Array<1 | 2 | 3 | 4 | 5 | 6> {
  if (stage.mode === "scenario") {
    if (stage.stage >= 1 && stage.stage <= 6) {
      return [stage.stage as 1 | 2 | 3 | 4 | 5 | 6];
    }
    return [1, 2, 3, 4, 5, 6];
  }
  const n = ((((stage.stage - 1) % 6) + 6) % 6) + 1;
  return [n as 1 | 2 | 3 | 4 | 5 | 6];
}

function stageDropPreview(stage: StageDef, opts?: { equipWeekly?: boolean; keySets?: boolean }): string {
  const setIds = [
    ...new Set(
      opts?.keySets && stage.dropSetPool?.length
        ? stage.dropSetPool
        : [stage.dropSetId],
    ),
  ];
  const chips = !stageDropsSymbols(stage)
    ? ""
    : setIds
    .flatMap((setId) => {
      const def = SYMBOL_SETS.find((x) => x.id === setId);
      const name = def?.nameKo ?? setId;
      if (opts?.keySets) {
        return [
          `<span class="stage-drop-piece" title="${escapeHtml(name)}">
        <img class="stage-drop-piece-ico" src="${symbolArtFallbackSrc(setId, 2)}" width="28" height="28" alt="${escapeHtml(name)}" draggable="false" />
      </span>`,
        ];
      }
      const slots = stageDropSlots(stage);
      return slots.map((slot) => {
        const label = `${name}${slot}`;
        return `<span class="stage-drop-piece" title="${label}">
        <img class="stage-drop-piece-ico" src="${symbolArtFallbackSrc(setId, slot)}" width="28" height="28" alt="${label}" draggable="false" />
        <span class="stage-drop-piece-label">${label}</span>
      </span>`;
      });
    })
        .join("");
  const hasGear =
    !!opts?.equipWeekly || (stage.gearDropChance ?? 0) > 0 || stage.mode === "equip";
  const gear = hasGear
    ? `<span class="stage-drop-piece stage-drop-piece--gear" title="${t('ui.759f762a02')}">
        <img class="stage-drop-piece-ico" src="/art/ui/gear/weapon.webp" width="28" height="28" alt="${t('ui.759f762a02')}" draggable="false" />
        <span class="stage-drop-piece-label">${t('ui.e17b206052')}</span>
      </span>`
    : "";
  const awakenEssences =
    stage.awakenElement && stage.awakenEssenceDrops
      ? stage.awakenEssenceDrops
          .map(
            (drop) => `<span class="stage-drop-piece" title="${escapeHtml(essenceGradeLabel(drop.grade))}">
        <img class="stage-drop-piece-ico" src="${essenceArtSrc(stage.awakenElement as SummonerElement, drop.grade)}" width="28" height="28" alt="" draggable="false" />
        <span class="stage-drop-piece-label">${drop.min}${drop.max > drop.min ? `-${drop.max}` : ""}</span>
      </span>`,
          )
          .join("")
      : "";
  const mat =
    stage.id === "weekday_skill"
      ? `<span class="stage-drop-piece" title="${escapeHtml(t("res.skillMats"))}">
        <img class="stage-drop-piece-ico" src="/art/ui/res/skill-mat.svg" width="28" height="28" alt="" draggable="false" />
      </span>`
      : "";
  return `<span class="stage-card-drops">${chips}${gear}${awakenEssences}${mat}</span>`;
}

function stageEnemyIds(stage: StageDef): string[] {
  if (stage.enemyWaves?.length) {
    return [...new Set(stage.enemyWaves.flat())];
  }
  return [...new Set(stage.enemyMonsterIds)];
}

function stageAppearingMons(stage: StageDef): string {
  const ids = stageEnemyIds(stage).slice(0, 6);
  if (!ids.length) return "";
  const icons = ids
    .map((id) => {
      const m = getMonster(id);
      const name = m?.nameKo ?? id;
      const grade = invGradeFromStars(m?.naturalStars ?? 1);
      return `<span class="stage-sortie-mon inv-grade--${grade}" title="${name}">
        ${monsterArtImg(id, "stage-sortie-mon-img", 32) || `<span class="stage-sortie-mon-fallback">${name.slice(0, 1)}</span>`}
      </span>`;
    })
    .join("");
  return `<div class="stage-sortie-mons" aria-label="${t("ui.stageAppearing")}">${icons}</div>`;
}

function stageListMarker(stage: StageDef, idx: number): string {
  if (stage.mode === "scenario") return `${stage.map}-${stage.stage}`;
  if (stage.cairosTier === "abyss_normal") return "AN";
  if (stage.cairosTier === "abyss_hard") return "AH";
  if (stage.mode === "depth" || stage.mode === "equip" || stage.mode === "challenge_tower") return String(stage.stage);
  return String(stage.stage > 0 ? stage.stage : idx + 1);
}

function stageButtons(list: StageDef[], opts?: { equipWeekly?: boolean; drops?: boolean }): string {
  const vaultLeft = opts?.equipWeekly
    ? equipVaultRemaining(syncEquipVaultWeek(save))
    : null;
  const energyNow = Math.floor(save.island.energy);
  return list
    .map((s, idx) => {
      const diff = effectiveDiff(s);
      const locked =
        !isStageUnlockedForDifficulty(save, s.id, diff) ||
        (vaultLeft !== null && vaultLeft <= 0);
      const done = isStageClearedOnDifficulty(save, s.id, diff);
      const diffOpen = isDifficultyOpen(save, s, diff);
      const cost = stageEnergyCost(s);
      const canOpen = !locked && diffOpen;
      const short = cost > energyNow && diffOpen;
      const marker = stageListMarker(s, idx);
      const costLabel = String(cost);
      const battleAria = !diffOpen
        ? t("ui.4292516afd")
        : `${marker} ${s.nameKo} ${MIDDOT} ${t("ui.stageBattle")} ${MIDDOT} ${t("ui.7dcdb553c8")} ${costLabel}`;
      const status = stageUnlockLabel(save, s, diff);
      const rowTitle =
        vaultLeft !== null
          ? `${s.nameKo} · ${t("ui.9cbaf58b88")} ${vaultLeft}/${EQUIP_VAULT_WEEKLY_LIMIT}`
          : `${s.nameKo} · ${status}`;
      const mid = opts?.drops
        ? stageDropPreview(s, { equipWeekly: opts.equipWeekly, keySets: true })
        : stageAppearingMons(s);
      return `<div class="stage-sortie${done ? " is-cleared" : ""}${locked ? " is-locked" : ""}${!canOpen ? " is-disabled" : ""}${short ? " is-short-energy" : ""}${
        onboard.step === "battle" && s.id === ONBOARD_FIRST_STAGE_ID
          ? " is-onboard-focus"
          : ""
      }" title="${escapeHtml(rowTitle)}">
        <span class="stage-sortie-mark${done ? " is-done" : ""}" aria-hidden="true">
          ${done ? `<span class="stage-sortie-check">${CHECK}</span>` : ""}
          <strong>${escapeHtml(marker)}</strong>
        </span>
        ${mid}
        <button type="button" class="stage-sortie-battle${short ? " is-short" : ""}" data-stage="${s.id}" data-core-stage="${s.id}" aria-label="${escapeHtml(battleAria)}" title="${!diffOpen ? t("ui.4292516afd") : escapeHtml(status)}" ${canOpen ? "" : "disabled"}>
          <span class="stage-sortie-cost" aria-hidden="true"><strong>${costLabel}</strong></span>
          <span class="stage-sortie-battle-label">${t("ui.stageBattle")}</span>
        </button>
      </div>`;
    })
    .join("");
}
type StagesRegion = {
  id: StagesRegionId;
  name: string;
  blurb: string;
  x: number;
  y: number;
  tone: string;
  stages: StageDef[];
  equipWeekly?: boolean;
  warena?: boolean;
  guild?: boolean;
  arena?: boolean;
};

function isMainQuestRegion(id: StagesRegionId): boolean {
  return MAIN_QUEST_PIN_LAYOUT.some((p) => p.id === id);
}

function stagesRegions(): StagesRegion[] {
  const mqRegions: StagesRegion[] = MAIN_QUEST_PIN_LAYOUT.map((pin) => ({
    id: pin.id,
    name: pin.areaKo,
    blurb: `${t('ui.9d96ebc162')} ${MIDDOT} ${pin.areaKo}`,
    x: pin.x,
    y: pin.y,
    tone: pin.tone,
    stages: stagesForMap(pin.map),
  }));
  const sideMeta: Record<
    string,
    {
      name: string;
      blurb: string;
      stages: StageDef[];
      equipWeekly?: boolean;
      warena?: boolean;
      guild?: boolean;
      arena?: boolean;
    }
  > = {
    depth: { name: t('ui.cd2bb578b4'), blurb: t('ui.7316fbbfa6'), stages: DEPTH_STAGES },
    arena: {
      name: t('ui.262553905b'),
      blurb: t('ui.be1af5568b'),
      stages: ARENA_STAGES,
      arena: true,
    },
    cadence: {
      name: t('ui.e0536c253c'),
      blurb: t('ui.4d59148e17'),
      stages: [...WEEKDAY_STAGES, ...TRIAL_STAGES],
    },
    equip: {
      name: t('ui.6003da6bd2'),
      blurb: t('ui.e00890de86'),
      stages: EQUIP_STAGES,
      equipWeekly: true,
    },
    warena: {
      name: t("stages.warena"),
      blurb: t("stages.warenaBlurb"),
      stages: WORLD_ARENA_STAGES,
      warena: true,
    },
    challenge_tower: {
      name: t("stages.challengeTower"),
      blurb: t("stages.challengeTowerBlurb"),
      stages: ALL_CHALLENGE_TOWER_STAGES,
    },
    guild: {
      name: t("stages.guildRaid"),
      blurb: t("stages.guildRaidBlurb"),
      stages: GUILD_RAID_STAGES,
      guild: true,
    },
  };
  const sideRegions: StagesRegion[] = SIDE_CONTENT_PIN_LAYOUT.map((pin) => {
    const meta = sideMeta[pin.id]!;
    return {
      id: pin.id,
      name: meta.name,
      blurb: `${meta.blurb} ${MIDDOT} ${pin.landmarkKo}`,
      x: pin.x,
      y: pin.y,
      tone: pin.id,
      stages: meta.stages,
      equipWeekly: meta.equipWeekly,
      warena: meta.warena,
      guild: meta.guild,
      arena: meta.arena,
    };
  });
  return [...mqRegions, ...sideRegions];
}

function regionProgress(stages: StageDef[]): {
  unlocked: boolean;
  cleared: number;
  total: number;
} {
  if (stages[0]?.mode === "challenge_tower") {
    const synced = syncChallengeTowerMonth(save);
    const cleared =
      challengeTowerFloor(synced) + challengeTowerFloor(synced, "hard");
    const total = CHALLENGE_TOWER_FLOORS * 2;
    const unlocked = isChallengeTowerContentUnlocked(save) && cleared < total;
    return { unlocked: unlocked || cleared > 0, cleared, total };
  }
  const cleared = stages.filter((s) => save.clearedStages.includes(s.id)).length;
  const unlocked = stages.some((s) => isStageUnlocked(save, s.id));
  return { unlocked, cleared, total: stages.length };
}

function isStagesRegionOpen(region: StagesRegion): boolean {
  if (!isSideRegionGuideOpen(onboard.step, region.id)) return false;
  return regionProgress(region.stages).unlocked;
}

/** Only the main-quest maps run Normal/Hard/Hell; everything else is floor-based. */
function regionUsesDifficulty(region: StagesRegion): boolean {
  return region.stages.some(stageUsesDifficulty);
}

function regionDifficultyOpen(region: StagesRegion, diff: StageDifficulty): boolean {
  if (diff === "normal") return true;
  return region.stages.some((s) => isDifficultyOpen(save, s, diff));
}

function resetCoreStageBindings(): void {
  unbindCoreStageMap?.();
  unbindCoreStageMap = null;
  coreStageMapViewport = null;
  unbindCoreStageRegion?.();
  unbindCoreStageRegion = null;
  unbindCoreStagePrep?.();
  unbindCoreStagePrep = null;
  coreStageRegionHost = null;
}

function openStagesRegionPin(regionId: string): void {
  const region = stagesRegions().find((candidate) => candidate.id === regionId);
  if (!region) return;
  if (!isStagesRegionOpen(region)) {
    flash(t("ui.b72f5a4752"));
    return;
  }
  const isSameRegion = stagesRegion === region.id;
  const next = isSameRegion ? null : region.id;
  stagesRegion = next;
  stageEntryId = null;
  stagesDepthDungeon = null;
  if (!isSameRegion) {
    stagesDropInfoOpen = false;
    stagesDropSetExpand = false;
    if (region.id === "mq1") {
      patchOnboard({ openedStages: true, openedRegion: true });
    } else {
      patchOnboard({ openedStages: true });
    }
  }
  applyStagesRegionOpen();
  if (
    stagesRegion === "mq1" &&
    (onboard.step === "stages" || onboard.step === "battle")
  ) {
    requestAnimationFrame(() => focusStagesRegion("mq1"));
  }
}

function bindCoreStageMap(): void {
  const viewport = app.querySelector<HTMLElement>("#stages-viewport");
  if (!viewport) {
    if (unbindCoreStageMap) {
      unbindCoreStageMap();
      unbindCoreStageMap = null;
      coreStageMapViewport = null;
    }
    return;
  }
  const stale =
    coreStageMapViewport !== viewport ||
    !unbindCoreStageMap ||
    !coreStageMapViewport?.isConnected;
  if (!stale) return;
  unbindCoreStageMap?.();
  coreStageMapViewport = viewport;
  unbindCoreStageMap = bindCoreStageMapController(viewport, {
    openRegion: openStagesRegionPin,
    locked: () => flash(t("ui.b72f5a4752")),
  });
}

function ensureCoreStageHostControllers(host: HTMLElement): void {
  const stale =
    coreStageRegionHost !== host ||
    !unbindCoreStageRegion ||
    !coreStageRegionHost?.isConnected;
  if (!stale) return;
  unbindCoreStageRegion?.();
  unbindCoreStagePrep?.();
  coreStageRegionHost = host;
  unbindCoreStageRegion = bindCoreStageRegionController(host, {
    openStage: (stageId) => {
      const stage = getStage(stageId);
      if (stage) openStagePrep(stage);
    },
    closeRegion: () => {
      stagesRegion = null;
      stageEntryId = null;
      stagesDepthDungeon = null;
      stagesDropInfoOpen = false;
      stagesDropSetExpand = false;
      applyStagesRegionOpen();
    },
  });
  unbindCoreStagePrep = bindCoreStagePrepController(host, {
    start: confirmStagePrepStart,
    cancel: closeStagePrep,
  });
}

/** Open/close/refresh the region sheet without redrawing the world map. */
function applyStagesRegionOpen(opts?: { animate?: boolean }): void {
  const animate = opts?.animate !== false;
  if (view === "stages") bindCoreStageMap();
  const host = app.querySelector<HTMLElement>("#stages-region-host");
  if (!host) return;
  ensureCoreStageHostControllers(host);

  app.querySelectorAll<HTMLButtonElement>("[data-region]").forEach((btn) => {
    btn.classList.toggle("is-active", btn.dataset.region === stagesRegion);
  });
  app.classList.toggle("stage-prep-open", view === "stages" && !!stageEntryId);
  app.classList.toggle(
    "stages-overlay-open",
    view === "stages" && (!!stagesRegion || !!stageEntryId),
  );

  const selected = stagesRegion
    ? stagesRegions().find((r) => r.id === stagesRegion) ?? null
    : null;
  if (!selected && !stageEntryId) {
    rememberOverlayClose("stage-prep");
    rememberOverlayClose("stages-region");
    host.innerHTML = "";
    return;
  }
  if (
    selected &&
    stageEntryDiff !== "normal" &&
    (!regionUsesDifficulty(selected) ||
      !regionDifficultyOpen(selected, stageEntryDiff))
  ) {
    stageEntryDiff = "normal";
  }
  const sheet = selected && !stageEntryId ? renderStagesRegionSheet(selected) : "";
  const prep = stageEntryId ? renderStageEntryModal() : "";
  host.innerHTML = `${sheet}${prep}`;
  const layer = host.querySelector<HTMLElement>(
    stageEntryId ? ".stage-prep-layer" : ".stages-region-layer",
  );
  if (animate) {
    if (layer) replayModalPop(layer);
  } else {
    suppressStageModalAnim(host);
  }
  if (selected && !stageEntryId) bindStagesRegionSheet();
  if (stageEntryId) bindStageEntryModal();
  if (stageEntryId) {
    rememberOverlayClose("stages-region");
    rememberOverlayOpen("stage-prep");
  } else {
    rememberOverlayClose("stage-prep");
    rememberOverlayOpen("stages-region");
  }
}

function bindStagesRegionSheet(): void {
  const host = app.querySelector("#stages-region-host");
  if (!host) return;
  ensureModalXDelegate();

  host.querySelector("#btn-region-drop-info")?.addEventListener("click", () => {
    stagesDropInfoOpen = !stagesDropInfoOpen;
    if (stagesDropInfoOpen) {
      stagesDropTab = "scroll";
      stagesDropSetExpand = false;
      applyStageDropInfo({ animate: true });
    } else {
      stagesDropSetExpand = false;
      applyStageDropInfo();
    }
  });

  if (stagesDropInfoOpen) bindStageDropInfoControls(host);

  host.querySelector("#region-diff-select")?.addEventListener("change", (ev) => {
    const v = (ev.target as HTMLSelectElement).value as StageDifficulty;
    if (v === "normal" || v === "hard" || v === "hell") {
      stageEntryDiff = v;
      applyStagesRegionOpen({ animate: false });
    }
  });

  host.querySelectorAll<HTMLButtonElement>("[data-ban-toggle]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.banToggle!;
      const cur = [...(save.arenaBanIds ?? [])];
      const idx = cur.indexOf(id);
      if (idx >= 0) cur.splice(idx, 1);
      else if (cur.length < 2) cur.push(id);
      else {
        flash(t("ui.522ab79351"));
        return;
      }
      const r = runSetArenaBans(save, cur);
      save = r.save;
      persist();
      flash(r.message);
      applyStagesRegionOpen({ animate: false });
    });
  });

  host.querySelector("#btn-season-claim")?.addEventListener("click", () => {
    const r = runClaimSeasonReward(save);
    save = r.save;
    persist();
    flash(r.message);
    applyStagesRegionOpen({ animate: false });
  });

  host.querySelectorAll<HTMLButtonElement>("[data-arena-opponent]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.arenaOpponent;
      if (!id || id === arenaSelectedOpponentId) return;
      arenaSelectedOpponentId = id;
      applyStagesRegionOpen({ animate: false });
    });
  });

  host.querySelector("#btn-arena-defense-edit")?.addEventListener("click", () => {
    openArenaDefenseEditor();
  });

  host.querySelector("#btn-arena-attack")?.addEventListener("click", () => {
    const opponent = ensureArenaSelectedOpponent();
    if (!opponent) return;
    const stage = getStage(opponent.stageId);
    if (!stage) return;
    if (!isStageUnlocked(save, opponent.stageId)) return;
    if (arenaAttacksRemaining(save) <= 0) return;
    arenaPrepOpponent = opponent;
    openStagePrep(stage);
  });

  host.querySelectorAll<HTMLButtonElement>("[data-warena-opponent]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.warenaOpponent;
      if (!id || id === warenaSelectedOpponentId) return;
      warenaSelectedOpponentId = id;
      applyStagesRegionOpen({ animate: false });
    });
  });

  host.querySelector("#btn-warena-defense-edit")?.addEventListener("click", () => {
    openArenaDefenseEditor();
  });

  host.querySelector("#btn-warena-attack")?.addEventListener("click", () => {
    const opponent = ensureWarenaSelectedOpponent();
    if (!opponent) return;
    const stage = getStage(opponent.stageId);
    if (!stage) return;
    if (!isStageUnlocked(save, opponent.stageId)) return;
    warenaPrepOpponent = opponent;
    openStagePrep(stage);
  });

  host.querySelectorAll<HTMLButtonElement>("[data-depth-dungeon]").forEach((btn) => {
    btn.addEventListener("click", () => {
      const id = btn.dataset.depthDungeon;
      if (id === "giant" || id === "dragon" || id === "necro") {
        stagesDepthDungeon = id;
        applyStagesRegionOpen({ animate: false });
      }
    });
  });
  host.querySelector("[data-depth-back]")?.addEventListener("click", () => {
    stagesDepthDungeon = null;
    applyStagesRegionOpen({ animate: false });
  });
  host
    .querySelectorAll<HTMLButtonElement>("[data-awaken-dungeon]")
    .forEach((btn) => {
      btn.addEventListener("click", () => {
        const element = btn.dataset.awakenDungeon as
          | SummonerElement
          | undefined;
        if (!element || btn.disabled) return;
        stagesAwakenElement = element;
        applyStagesRegionOpen({ animate: false });
      });
    });
  host.querySelector("[data-awaken-back]")?.addEventListener("click", () => {
    stagesAwakenElement = null;
    applyStagesRegionOpen({ animate: false });
  });
  host.querySelectorAll<HTMLButtonElement>("[data-core-stage]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.preventDefault();
      ev.stopPropagation();
      if (btn.disabled) return;
      const stage = getStage(btn.dataset.coreStage ?? "");
      if (stage) openStagePrep(stage);
    });
  });
  bindCommunityActions(host);
}

/** Symbols only roll where `dropChance` is left open; awaken floors pay essence instead. */
function stageDropsSymbols(stage: StageDef): boolean {
  if (stage.awakenElement) return false;
  return (stage.dropChance ?? 1) > 0;
}

/** Mirrors the `defaultGearChance` table in `applyRewards`. */
function stageDropsGear(stage: StageDef): boolean {
  if (stage.mode === "equip") return true;
  if (stage.gearDropChance != null) return stage.gearDropChance > 0;
  return (
    stage.mode === "scenario" ||
    stage.mode === "depth" ||
    stage.mode === "weekday" ||
    stage.mode === "trial"
  );
}

/** PVP regions hand out glory only — the drop sheet has nothing to show there. */
function regionHasDrops(region: StagesRegion): boolean {
  if (region.id === "challenge_tower") return true;
  return region.stages.some(
    (s) => stageDropsSymbols(s) || stageDropsGear(s) || !!s.awakenElement,
  );
}

function regionPrimaryDropSet(region: StagesRegion): (typeof SYMBOL_SETS)[number] | null {
  const counts = new Map<string, number>();
  for (const s of region.stages) {
    if (!stageDropsSymbols(s)) continue;
    counts.set(s.dropSetId, (counts.get(s.dropSetId) ?? 0) + 1);
  }
  if (counts.size === 0) return null;
  let bestId = region.stages[0]?.dropSetId;
  let bestN = 0;
  for (const [id, n] of counts) {
    if (n > bestN) {
      bestId = id as typeof bestId;
      bestN = n;
    }
  }
  if (!bestId) return null;
  return SYMBOL_SETS.find((x) => x.id === bestId) ?? null;
}

function cairosCosmeticSlotNum(setId: string, artSlot: number): number {
  let h = cairosDropCosmeticSeed ^ artSlot;
  for (let i = 0; i < setId.length; i++) {
    h = Math.imul(h ^ setId.charCodeAt(i), 2654435761);
  }
  return ((h >>> 0) % 6) + 1;
}

function cairosDungeonDropMeta(floors: StageDef[]): {
  minStar: number;
  maxStar: number;
  setIds: string[];
} {
  const setIds = [
    ...new Set(
      floors.flatMap((s) =>
        s.dropSetPool?.length ? s.dropSetPool : [s.dropSetId],
      ),
    ),
  ];
  let minStar = 99;
  let maxStar = 0;
  for (const stage of floors) {
    for (const w of stage.starWeights ?? []) {
      minStar = Math.min(minStar, w.value);
      maxStar = Math.max(maxStar, w.value);
    }
  }
  if (minStar > maxStar) {
    minStar = 1;
    maxStar = 6;
  }
  return { minStar, maxStar, setIds };
}

function cairosGradeRangeHtml(): string {
  const rare = symbolQualityMeta("rare");
  const legend = symbolQualityMeta("legend");
  return `<span class="cairos-drop-range cairos-drop-range--grade">
    <span class="gear-detail-grade rarity--${rare.id}">${escapeHtml(rare.label)}</span>
    <span class="cairos-drop-range-sep" aria-hidden="true">~</span>
    <span class="gear-detail-grade rarity--${legend.id}">${escapeHtml(legend.label)}</span>
  </span>`;
}

function renderCairosStageDropInfoModal(region: StagesRegion): string {
  if (!stagesDepthDungeon) return "";
  const floors = cairosStagesFor(stagesDepthDungeon);
  const { minStar, maxStar, setIds } = cairosDungeonDropMeta(floors);
  const starRange = t("ui.cairosDropStarRange", { min: minStar, max: maxStar });
  const symbolTiles = setIds
    .map((setId) => {
      const def = SYMBOL_SETS.find((x) => x.id === setId);
      const name = def?.nameKo ?? setId;
      const pieces = ([1, 2, 3, 4, 5, 6] as const)
        .map((artSlot) => {
          const num = cairosCosmeticSlotNum(setId, artSlot);
          return `<span class="cairos-drop-piece" title="${escapeHtml(name)}">
            ${symbolArtImg(setId, artSlot, "cairos-drop-piece-art", 48)}
            <span class="cairos-drop-piece-num" aria-hidden="true">${num}</span>
          </span>`;
        })
        .join("");
      return `<div class="cairos-drop-set">
        <div class="cairos-drop-pieces">${pieces}</div>
        <span class="cairos-drop-set-name">${escapeHtml(name)}</span>
      </div>`;
    })
    .join("");

  return `<div class="stage-drop-info-layer" id="stage-drop-info-layer" role="presentation">
    <button type="button" class="stage-drop-info-backdrop" id="btn-stage-drop-info-close" aria-label="${t("ui.94b7dba159")}"></button>
    <div class="stage-drop-info-modal stage-drop-info-modal--cairos" role="dialog" aria-modal="true" aria-labelledby="stage-drop-info-title">
      ${modalCloseX(t("ui.94b7dba159"), "btn-stage-drop-info-close")}
      <h2 class="stage-drop-info-title" id="stage-drop-info-title">${escapeHtml(t("ui.stageDropInfo"))}</h2>
      <div class="cairos-drop-meta">
        <span class="cairos-drop-range cairos-drop-range--stars">${escapeHtml(starRange)}</span>
        ${cairosGradeRangeHtml()}
      </div>
      <div class="cairos-drop-symbols">${symbolTiles}</div>
    </div>
  </div>`;
}

function stageDropInfoRow(opts: {
  icon: string;
  name: string;
  sub?: string;
}): string {
  return `<div class="stage-drop-info-row">
    <span class="stage-drop-info-ico" aria-hidden="true"><img src="${opts.icon}" width="44" height="44" alt="" draggable="false" /></span>
    <span class="stage-drop-info-copy">
      <strong>${opts.name}</strong>
      ${opts.sub ? `<small>${opts.sub}</small>` : ""}
    </span>
  </div>`;
}

function renderStageDropInfoModal(region: StagesRegion): string {
  if (!stagesDropInfoOpen || !regionHasDrops(region)) return "";
  if (region.id === "depth" && stagesDepthDungeon) {
    return renderCairosStageDropInfoModal(region);
  }
  if (region.id === "challenge_tower") {
    return `<div class="stage-drop-info-layer" id="stage-drop-info-layer" role="presentation">
    <button type="button" class="stage-drop-info-backdrop" id="btn-stage-drop-info-close" aria-label="${t("ui.94b7dba159")}"></button>
    <div class="stage-drop-info-modal" role="dialog" aria-modal="true" aria-labelledby="stage-drop-info-title">
      ${modalCloseX(t("ui.94b7dba159"), "btn-stage-drop-info-close")}
      <h2 class="stage-drop-info-title" id="stage-drop-info-title">${escapeHtml(t("ui.stageDropInfo"))}</h2>
      <div class="stage-drop-info-rows">
        ${stageDropInfoRow({
          icon: scrollArtSrc("legend"),
          name: t("ui.stageDropScrollLegend"),
          sub: "100F",
        })}
      </div>
    </div>
  </div>`;
  }
  const set = regionPrimaryDropSet(region);
  const setBonus = set
    ? t("ui.stageDropSetBonus", { n: set.pieces, effect: set.effectKo })
    : t("ui.setBonusNone");
  const setIco = set ? symbolSetArtSrc(set.id) : symbolEmptySlotArtSrc(1);
  const setIcoFallback = set
    ? symbolSetArtFallbackSrc(set.id)
    : symbolEmptySlotArtFallbackSrc(1);
  const setName = set?.nameKo ?? "—";
  const pieceExpand = stagesDropSetExpand && set
    ? `<div class="stage-drop-info-pieces">${[1, 2, 3, 4, 5, 6]
        .map(
          (slot) =>
            `<span class="stage-drop-info-piece" title="${t("ui.stageDropPiece", { name: set.nameKo, slot })}">
              ${symbolArtImg(set.id, slot, "", 36)}
              <small>${set.nameKo}${slot}</small>
            </span>`,
        )
        .join("")}</div>`
    : "";

  const scrollRows = [
    stageDropInfoRow({
      icon: scrollArtSrc("normal"),
      name: t("ui.stageDropScrollNormal"),
    }),
  ];
  if (
    regionUsesDifficulty(region) &&
    (stageEntryDiff === "hard" || stageEntryDiff === "hell")
  ) {
    scrollRows.push(
      stageDropInfoRow({
        icon: scrollArtSrc("premium"),
        name: t("ui.stageDropScrollPremium"),
      }),
    );
  }

  const gearSlotIds: GearSlot[] = [...GEAR_SLOTS];
  const gearRows = [
    stageDropInfoRow({
      icon: "/art/ui/gear/weapon.webp",
      name: t("ui.stageDropGearRandom"),
      sub: t("ui.stageDropGearRandomHint"),
    }),
    ...gearSlotIds.map((slot) =>
      stageDropInfoRow({
        icon: gearSlotArtSrc(slot),
        name: gearSlotLabel(slot),
      }),
    ),
  ];

  const bodyRows =
    stagesDropTab === "gear" ? gearRows.join("") : scrollRows.join("");

  return `<div class="stage-drop-info-layer" id="stage-drop-info-layer" role="presentation">
    <button type="button" class="stage-drop-info-backdrop" id="btn-stage-drop-info-close" aria-label="${t("ui.94b7dba159")}"></button>
    <div class="stage-drop-info-modal" role="dialog" aria-modal="true" aria-labelledby="stage-drop-info-title">
      ${modalCloseX(t("ui.94b7dba159"), "btn-stage-drop-info-close")}
      <h2 class="sr-only" id="stage-drop-info-title">${t("ui.stageDropInfo")}</h2>

      <section class="stage-drop-info-block">
        <div class="stage-drop-info-tabs stage-drop-info-tabs--solo">
          <span class="stage-drop-info-tab is-on">${t("ui.60fbf51b13")}</span>
        </div>
        <div class="stage-drop-info-panel">
          <div class="stage-drop-info-row stage-drop-info-row--set">
            <span class="stage-drop-info-ico" aria-hidden="true"><img src="${setIco}" width="44" height="44" alt="" draggable="false"${setIcoFallback ? ` onerror="this.onerror=null;this.src='${setIcoFallback}'"` : ""} /></span>
            <span class="stage-drop-info-copy">
              <strong>${setName}</strong>
              <small>${setBonus}</small>
            </span>
            <button type="button" class="stage-drop-info-more${stagesDropSetExpand ? " is-on" : ""}" id="btn-stage-drop-set-more" aria-expanded="${stagesDropSetExpand ? "true" : "false"}" aria-label="${t("ui.stageDropSetMore")}" title="${t("ui.stageDropSetMore")}">
              <span aria-hidden="true">${MIDDOT}${MIDDOT}${MIDDOT}</span>
            </button>
          </div>
          ${pieceExpand}
        </div>
      </section>

      <section class="stage-drop-info-block">
        <div class="stage-drop-info-tabs" role="tablist" aria-label="${t("ui.stageDropInfo")}">
          <button type="button" class="stage-drop-info-tab${stagesDropTab === "scroll" ? " is-on" : ""}" role="tab" aria-selected="${stagesDropTab === "scroll" ? "true" : "false"}" data-drop-tab="scroll">${t("ui.fa73f3a42f")}</button>
          <button type="button" class="stage-drop-info-tab${stagesDropTab === "gear" ? " is-on" : ""}" role="tab" aria-selected="${stagesDropTab === "gear" ? "true" : "false"}" data-drop-tab="gear">${t("ui.stageDropGear")}</button>
        </div>
        <div class="stage-drop-info-panel" role="tabpanel">
          ${bodyRows}
        </div>
      </section>
    </div>
  </div>`;
}

function isBossPrepStage(stage: StageDef): boolean {
  return (
    !!stage.bossMonsterId ||
    stage.mode === "guild_raid" ||
    stage.mode === "weekday" ||
    stage.mode === "equip" ||
    stage.mode === "trial"
  );
}

function pvpRivalSummoner(el: SummonerElement, name: string): string {
  return `<div class="pvp-rival-summoner el-${el}">
    <img class="pvp-rival-sum-img" src="${summonerArtSrc(el)}" width="48" height="48" alt="" draggable="false" decoding="async" />
    <span class="pvp-rival-sum-name">${escapeHtml(name)}</span>
  </div>`;
}

function pvpRivalPowerRow(ally: number, enemy: number, gap: number): string {
  return `<div class="pvp-rival-power" title="${escapeHtml(t("ui.arena.power"))}">
    <span><strong>${fmtRes(ally)}</strong></span>
    <span class="pvp-rival-power-vs" aria-hidden="true">VS</span>
    <span><strong>${fmtRes(enemy)}</strong></span>
    <span class="pvp-rival-power-gap${gap >= 0 ? " is-up" : " is-down"}">${gap >= 0 ? "+" : ""}${fmtRes(gap)}</span>
  </div>`;
}

function pvpRivalPortraits(ids: string[]): string {
  return `<div class="pvp-rival-mons">${ids
    .slice(0, 4)
    .map((id) => {
      const m = getMonster(id);
      const grade = invGradeFromStars(m?.naturalStars ?? 1);
      return `<span class="pvp-rival-mon inv-grade--${grade}"${monsterSlotFamilyAttr(id)} title="${escapeHtml(m?.nameKo ?? id)}">${monsterArtImg(id, "pvp-rival-mon-img", 40) || ""}</span>`;
    })
    .join("")}</div>`;
}

/** NPC practice tiers first, then the rotating rival ladder. */
function allArenaOpponents(): ArenaOpponent[] {
  return [...listArenaNpcOpponents(), ...listDailyArenaOpponents()];
}

function ensureArenaSelectedOpponent(): ArenaOpponent | null {
  const opponents = allArenaOpponents();
  if (!opponents.length) return null;
  if (arenaSelectedOpponentId) {
    const found = opponents.find((o) => o.id === arenaSelectedOpponentId);
    if (found) return found;
  }
  arenaSelectedOpponentId = opponents[0]!.id;
  return opponents[0]!;
}

function renderArenaDefenseStripSlots(): string {
  const def = save.arenaDefense;
  if (!def?.party?.length) {
    return `<span class="arena-defense-empty">${escapeHtml(t("ui.arena.defenseEmpty"))}</span>`;
  }
  const sumEl = def.summoner ?? save.activeSummoner ?? "light";
  const summoner = `<span class="arena-defense-sum el-${sumEl}" title="${escapeHtml(t("ui.stagePrepSummoner"))}">
    <img class="arena-defense-sum-img" src="${summonerArtSrc(sumEl)}" width="40" height="40" alt="" draggable="false" decoding="async" />
  </span>`;
  const mons = [0, 1, 2, 3]
    .map((i) => {
      const uid = def.party[i];
      if (!uid) {
        return `<span class="arena-defense-slot empty" aria-hidden="true"></span>`;
      }
      const m = save.roster.find((x) => x.uid === uid);
      if (!m) {
        return `<span class="arena-defense-slot empty" aria-hidden="true"></span>`;
      }
      const defMon = getMonster(m.monsterId);
      const grade = invGradeFromStars(defMon?.naturalStars ?? 1);
      return `<span class="arena-defense-slot inv-grade--${grade}"${monsterSlotFamilyAttr(m.monsterId)} title="${escapeHtml(describeOwned(m))}">
        ${ownedMonsterArtImg(m, "arena-defense-slot-img", 40) || ""}
      </span>`;
    })
    .join("");
  return `${summoner}<div class="arena-defense-mons">${mons}</div>`;
}

function ensureWarenaSelectedOpponent(): ArenaOpponent | null {
  const opponents = listDailyWorldArenaOpponents();
  if (!opponents.length) return null;
  if (warenaSelectedOpponentId) {
    const found = opponents.find((o) => o.id === warenaSelectedOpponentId);
    if (found) return found;
  }
  warenaSelectedOpponentId = opponents[0]!.id;
  return opponents[0]!;
}

function warenaEnemyIdsVisible(ids: string[]): string[] {
  const bans = new Set(save.arenaBanIds ?? []);
  const filtered = ids.filter((id) => !bans.has(id));
  return filtered.length > 0 ? filtered : ids.slice(0, 1);
}

function renderPvpDefenseStrip(editBtnId: string): string {
  return `<div class="arena-my-defense-strip">
    <span class="arena-defense-label">${escapeHtml(t("ui.arena.myDefense"))}</span>
    <div class="arena-defense-preview">${renderArenaDefenseStripSlots()}</div>
    <button type="button" class="arena-defense-edit" id="${editBtnId}">${escapeHtml(t("ui.arena.editDefense"))}</button>
  </div>`;
}

/** Highest natural grade in the opposing deck — the card's ★ badge. */
function pvpDeckTopStars(enemyMonsterIds: string[]): number {
  return enemyMonsterIds.reduce(
    (best, id) => Math.max(best, getMonster(id)?.naturalStars ?? 1),
    1,
  );
}

function renderPvpOpponentCard(
  opponent: ArenaOpponent,
  selected: boolean,
  locked: boolean,
  pickAttr: "arena-opponent" | "warena-opponent",
): string {
  const levelLabel = t("ui.arena.level", { level: opponent.level });
  const stars = pvpDeckTopStars(opponent.enemyMonsterIds);
  const grade = invGradeFromStars(stars);
  const isNpc = opponent.kind === "npc";
  return `<button type="button" class="pvp-opp-card inv-grade--${grade}${selected ? " is-selected" : ""}${locked ? " is-locked" : ""}" role="listitem" data-${pickAttr}="${escapeHtml(opponent.id)}" aria-label="${escapeHtml(`${opponent.nickname} ${levelLabel}`)}" aria-pressed="${selected ? "true" : "false"}">
    <span class="pvp-opp-card-art el-${opponent.summonerElement}">
      <img class="pvp-opp-card-img" src="${summonerArtSrc(opponent.summonerElement)}" width="72" height="72" alt="" draggable="false" decoding="async" />
      ${isNpc ? `<span class="pvp-opp-card-npc">${escapeHtml(t("ui.arena.npcBadge"))}</span>` : ""}
      <span class="mon-slot-stars-overlay" aria-label="${stars}">${monStarsHtml(stars)}</span>
      <span class="mon-slot-lv-overlay">Lv.${opponent.level}</span>
    </span>
    <strong class="pvp-opp-card-name">${escapeHtml(opponent.nickname)}</strong>
    <span class="pvp-opp-card-foot">
      <span class="pvp-opp-card-rating">${fmtRes(opponent.rating)}</span>
      ${resChip("/art/ui/res/glory.svg", opponent.gloryReward, t("res.glory"))}
    </span>
  </button>`;
}

function renderPvpDeckDock(
  opponent: ArenaOpponent,
  opts: {
    mode: "arena" | "warena";
    attackBtnId: string;
    enemyIds: string[];
    locked: boolean;
  },
): string {
  const stage = getStage(opponent.stageId);
  const myRating = save.arenaRating ?? DEFAULT_ARENA_RATING;
  const power = stage
    ? estimateSortiePower(save, stage, {
        enemyMonsterIds: opts.enemyIds,
        party: [...save.party],
      })
    : null;
  const gap = power ? power.ally - power.enemy : 0;
  const enemyMonSlots = [0, 1, 2, 3]
    .map((i) => {
      const id = opts.enemyIds[i];
      if (!id) {
        return `<div class="stage-prep-slot empty" aria-hidden="true"></div>`;
      }
      const m = getMonster(id);
      const stars = Math.max(1, m?.naturalStars ?? 1);
      const grade = invGradeFromStars(stars);
      return `<div class="stage-prep-slot inv-grade--${grade} el-${m?.element ?? "dark"}"${monsterSlotFamilyAttr(id)} title="${escapeHtml(m?.nameKo ?? id)}">
        <span class="stage-prep-slot-art">${monsterArtImg(id, "stage-prep-slot-img", 48) || "?"}</span>
        ${stagePrepSlotOverlays({ level: opponent.level, stars })}
      </div>`;
    })
    .join("");
  const powerRow = power ? pvpRivalPowerRow(power.ally, power.enemy, gap) : "";
  const ticketChip =
    opts.mode === "arena"
      ? `<span class="pvp-rival-ticket-cost" aria-hidden="true"><img class="res-ico" src="/art/ui/res/arena-ticket.svg" width="14" height="14" alt="" draggable="false" /><strong>1</strong></span>`
      : "";
  const scoreSwing =
    opponent.kind === "npc"
      ? `+${ARENA_NPC_RATING_GAIN}`
      : `${MINUS}${Math.abs(applyArenaElo(myRating, opponent.rating, false).delta)} / +${applyArenaElo(myRating, opponent.rating, true).delta}`;
  const summonerAwaken = stage ? sortiePrepEnemySummonerAwaken(stage) : 0;
  return `<div class="arena-deck-dock" id="arena-deck-dock">
    <div class="arena-deck-dock-head">
      <div class="arena-deck-dock-summoner el-${opponent.summonerElement}">
        <img class="arena-deck-dock-sum-img" src="${summonerArtSrc(opponent.summonerElement)}" width="48" height="48" alt="" draggable="false" decoding="async" />
        <span class="arena-deck-dock-sum-name">${escapeHtml(opponent.nickname)}</span>
        <span class="arena-deck-dock-sum-level">${escapeHtml(t("ui.arena.level", { level: opponent.level }))}</span>
      </div>
      <div class="arena-deck-dock-rating">
        <span>${escapeHtml(t("ui.arena.rating"))}</span>
        <strong>${fmtRes(myRating)}</strong>
        <span aria-hidden="true">VS</span>
        <strong>${fmtRes(opponent.rating)}</strong>
        <span class="arena-deck-dock-swing">${escapeHtml(scoreSwing)}</span>
      </div>
    </div>
    <div class="stage-prep-slots arena-deck-dock-slots">
      <div class="stage-prep-slot stage-prep-slot--summoner el-${opponent.summonerElement}">
        <span class="stage-prep-slot-art">
          <img class="stage-prep-slot-img" src="${summonerArtSrc(opponent.summonerElement)}" width="48" height="48" alt="" draggable="false" decoding="async" />
        </span>
        ${stagePrepSummonerOverlays({ level: opponent.level, awaken: summonerAwaken })}
      </div>
      ${enemyMonSlots}
    </div>
    ${powerRow ? `<div class="arena-deck-dock-power">${powerRow}</div>` : ""}
    <button type="button" class="auth-btn-primary full arena-deck-dock-attack" id="${opts.attackBtnId}" ${opts.locked ? "disabled" : ""}>
      <span>${escapeHtml(t("ui.arena.attack"))}</span>
      ${ticketChip}
    </button>
  </div>`;
}

function renderPvpOpponentGrid(
  opponents: ArenaOpponent[],
  selectedId: string | null,
  isLocked: (opponent: ArenaOpponent) => boolean,
  pickAttr: "arena-opponent" | "warena-opponent",
  label: string,
): string {
  return `<div class="pvp-opp-grid" role="list" aria-label="${escapeHtml(label)}">${opponents
    .map((o) =>
      renderPvpOpponentCard(o, selectedId === o.id, isLocked(o), pickAttr),
    )
    .join("")}</div>`;
}

function renderArenaDeckDock(opponent: ArenaOpponent): string {
  const attacksLeft = arenaAttacksRemaining(save);
  const stage = getStage(opponent.stageId);
  const locked =
    !stage ||
    !isStageUnlocked(save, opponent.stageId) ||
    attacksLeft <= 0;
  return renderPvpDeckDock(opponent, {
    mode: "arena",
    attackBtnId: "btn-arena-attack",
    enemyIds: opponent.enemyMonsterIds.slice(0, 4),
    locked,
  });
}

function renderArenaRegionBody(): string {
  const selected = ensureArenaSelectedOpponent();
  const attacksLeft = arenaAttacksRemaining(save);
  const locked = (o: ArenaOpponent) =>
    !isStageUnlocked(save, o.stageId) || attacksLeft <= 0;
  const npcLabel = t("ui.arena.npcTiers");
  const rivalLabel = t("ui.arena.opponents");
  const dock = selected ? renderArenaDeckDock(selected) : "";
  return `<div class="arena-region-body">
    <div class="arena-sheet-top">
      ${renderPvpDefenseStrip("btn-arena-defense-edit")}
    </div>
    <div class="arena-opponent-list">
      <h4 class="pvp-opp-group-title">${escapeHtml(npcLabel)}</h4>
      ${renderPvpOpponentGrid(listArenaNpcOpponents(), selected?.id ?? null, locked, "arena-opponent", npcLabel)}
      <h4 class="pvp-opp-group-title">${escapeHtml(rivalLabel)}</h4>
      ${renderPvpOpponentGrid(listDailyArenaOpponents(), selected?.id ?? null, locked, "arena-opponent", rivalLabel)}
    </div>
    ${dock}
  </div>`;
}

function renderWarenaBanRow(): string {
  const banPool = [
    ...new Set(WORLD_ARENA_STAGES.flatMap((s) => s.enemyMonsterIds)),
  ];
  const bans = save.arenaBanIds ?? [];
  return `<div class="ban-row warena-ban-row">${banPool
    .map((id) => {
      const m = getMonster(id);
      const on = bans.includes(id);
      return `<button type="button" class="ban-chip${on ? " active" : ""}" data-ban-toggle="${id}">
          <span class="ban-chip-mark" aria-hidden="true">${on ? Mark.banOn : Mark.banOff}</span>
          <span class="ban-chip-body">
            <strong>${m?.nameKo ?? id}</strong>
          </span>
        </button>`;
    })
    .join("")}</div>`;
}

function renderWarenaRegionBody(): string {
  const opponents = listDailyWorldArenaOpponents();
  const selected = ensureWarenaSelectedOpponent();
  const seasonWins = save.arenaSeasonWins ?? 0;
  const rivalLabel = t("ui.arena.opponents");
  const dock = selected
    ? renderPvpDeckDock(selected, {
        mode: "warena",
        attackBtnId: "btn-warena-attack",
        enemyIds: warenaEnemyIdsVisible(selected.enemyMonsterIds).slice(0, 4),
        locked: !isStageUnlocked(save, selected.stageId),
      })
    : "";
  return `<div class="arena-region-body arena-region-body--warena">
    <div class="arena-sheet-top">
      <div class="warena-season-strip">
        <span class="guild-chip">${escapeHtml(t("ui.b78477b088"))}<strong>${seasonWins}</strong></span>
        <button type="button" class="auth-btn-primary warena-season-claim" id="btn-season-claim">${escapeHtml(t("ui.8b8572eda1"))}</button>
      </div>
      ${renderWarenaBanRow()}
      ${renderPvpDefenseStrip("btn-warena-defense-edit")}
    </div>
    <div class="arena-opponent-list">
      ${renderPvpOpponentGrid(opponents, selected?.id ?? null, (o) => !isStageUnlocked(save, o.stageId), "warena-opponent", rivalLabel)}
    </div>
    ${dock}
  </div>`;
}

function renderGuildRaidRegionBody(): string {
  if (!save.guildName) {
    return `<div class="guild-join-actions">
      <button type="button" class="auth-btn-ghost guild-ghost" id="btn-guild-join">${escapeHtml(t("ui.8b92576f2b"))}</button>
      <button type="button" class="auth-btn-primary guild-cta" id="btn-guild-create">
        <span class="guild-cta-label">${escapeHtml(t("ui.guild.create"))}</span>
      </button>
    </div>`;
  }
  const raidSave = syncRaidWeek(save);
  const raidHp = raidSave.raidBossHp ?? RAID_BOSS_MAX_HP;
  const raidLeft = raidAttemptsRemaining(raidSave);
  const raidPct = RAID_BOSS_MAX_HP ? (raidHp / RAID_BOSS_MAX_HP) * 100 : 0;
  const canFight = raidLeft > 0 && isStageUnlocked(save, "guild_raid_boss");
  return `<section class="guild-raid-sheet">
    <header class="guild-card-head">
      <span class="guild-card-kicker">${escapeHtml(t("ui.3ea974d72f"))}</span>
      <strong class="guild-card-val">${fmtRes(raidHp)} / ${fmtRes(RAID_BOSS_MAX_HP)}</strong>
    </header>
    ${guildBarHtml(raidPct, "hp")}
    <div class="guild-card-foot">
      <span class="guild-chip">${escapeHtml(t("ui.guild.raidAttempts"))}${guildAttemptPips(raidLeft, RAID_ATTEMPTS_DAILY)}</span>
      <span class="guild-chip" title="${escapeHtml(t("res.guild"))}"><img class="res-ico" src="/art/ui/res/guild.svg" width="14" height="14" alt="" draggable="false" /><strong>${fmtRes(save.guildContribution ?? 0)}</strong></span>
    </div>
    <button type="button" class="auth-btn-primary full guild-cta" data-stage="guild_raid_boss" data-core-stage="guild_raid_boss" ${canFight ? "" : "disabled"}>
      <span class="guild-cta-label">${escapeHtml(t("ui.stageBattle"))}</span>
      ${resChip("/art/ui/res/energy.svg", GUILD_RAID_STAGES[0]?.energyCost ?? 10, t("res.energy"))}
    </button>
  </section>`;
}

function cairosDungeonPortraitHtml(dungeon: CairosDungeon): string {
  const circle = `/art/battle/circle/cairos-${dungeon}.webp`;
  const boss = `/art/battle/boss/cairos-${dungeon}-front.webp`;
  return `<span class="dungeon-pick-portrait"><img class="dungeon-pick-portrait-img" src="${boss}" width="96" height="96" alt="" draggable="false" onerror="this.onerror=null;this.src='${circle}'" /></span>`;
}

function cairosDungeonSymbolTypesHtml(stage: StageDef): string {
  return stageDropPreview(stage, { keySets: true });
}

function renderCairosRegionBody(): string {
  const dungeons: { id: CairosDungeon; key: "ui.dungeon.giant" | "ui.dungeon.dragon" | "ui.dungeon.necro" }[] = [
    { id: "giant", key: "ui.dungeon.giant" },
    { id: "dragon", key: "ui.dungeon.dragon" },
    { id: "necro", key: "ui.dungeon.necro" },
  ];
  if (!stagesDepthDungeon) {
    return `<div class="dungeon-pick-list dungeon-pick-list--depth">${dungeons
      .map((d) => {
        const floors = cairosStagesFor(d.id);
        const sample = floors[floors.length - 1] ?? floors[0]!;
        return `<button type="button" class="dungeon-pick-card dungeon-pick-card--depth" data-depth-dungeon="${d.id}">
          ${cairosDungeonPortraitHtml(d.id)}
          <span class="dungeon-pick-main">
            <strong class="dungeon-pick-name">${escapeHtml(t(d.key))}</strong>
            <span class="dungeon-pick-symbols">${cairosDungeonSymbolTypesHtml(sample)}</span>
          </span>
        </button>`;
      })
      .join("")}</div>`;
  }
  const floors = cairosStagesFor(stagesDepthDungeon);
  const titleKey =
    stagesDepthDungeon === "giant"
      ? "ui.dungeon.giant"
      : stagesDepthDungeon === "dragon"
        ? "ui.dungeon.dragon"
        : "ui.dungeon.necro";
  return `<div class="dungeon-floor-wrap dungeon-floor-wrap--depth">
    <button type="button" class="nav-back nav-back--labeled dungeon-floor-back" data-depth-back aria-label="${escapeHtml(t("ui.dungeon.back"))}">
      <img class="nav-back-ico" src="/art/ui/back-arrow.svg" width="18" height="18" alt="" draggable="false" />
      <span class="nav-back-label">${ARROW_LEFT}${escapeHtml(t("ui.dungeon.back"))}</span>
    </button>
    <h3 class="dungeon-floor-title">${escapeHtml(t(titleKey))}</h3>
    <div class="stage-list stage-list--expedition stage-list--dungeon">${stageButtons(floors)}</div>
  </div>`;
}

function renderCadenceRegionBody(): string {
  const awakenStages = WEEKDAY_STAGES.filter((stage) => stage.awakenElement);
  if (stagesAwakenElement) {
    const floors = awakenStages.filter(
      (stage) => stage.awakenElement === stagesAwakenElement,
    );
    const title = floors[0]?.nameKo.replace(/\s+B\d+$/, "") ?? "";
    return `<div class="dungeon-floor-wrap">
      <button type="button" class="dungeon-floor-back" data-awaken-back>${escapeHtml(t("ui.dungeon.back"))}</button>
      <h3 class="dungeon-floor-title">${escapeHtml(title)}</h3>
      <div class="stage-list stage-list--expedition stage-list--dungeon">${stageButtons(floors, { drops: true })}</div>
    </div>`;
  }
  const elements = [
    "dark",
    "fire",
    "water",
    "wind",
    "light",
  ] as const;
  const cards = elements
    .map((element) => {
      const floors = awakenStages.filter(
        (stage) => stage.awakenElement === element,
      );
      const sample = floors[floors.length - 1] ?? floors[0];
      if (!sample) return "";
      const openToday = isWeekdayStageOpenToday(sample.id);
      const unlocked = isStageUnlocked(save, floors[0]!.id);
      const highestCleared = floors.reduce(
        (best, stage) =>
          save.clearedStages.includes(stage.id)
            ? Math.max(best, stage.stage)
            : best,
        0,
      );
      const highest = Math.min(10, highestCleared + 1);
      const title = sample.nameKo.replace(/\s+B\d+$/, "");
      const status = openToday
        ? t("ui.awakenOpenToday")
        : t(`ui.awakenOpenDay.${element}`);
      const essenceIcons = (["low", "mid", "high"] as const)
        .map(
          (grade) => `<img class="stage-drop-piece-ico" src="${essenceArtSrc(element, grade)}" width="28" height="28" alt="${escapeHtml(essenceGradeLabel(grade))}" draggable="false" />`,
        )
        .join("");
      return `<button type="button" class="dungeon-pick-card${!openToday || !unlocked ? " is-locked" : ""}" data-awaken-dungeon="${element}" ${openToday && unlocked ? "" : "disabled"}>
        <img class="dungeon-pick-art" src="/art/battle/circle/awaken-${element}.webp" width="160" height="160" alt="" draggable="false" />
        <strong class="dungeon-pick-name">${escapeHtml(title)}</strong>
        <span class="stage-card-drops">${essenceIcons}</span>
        <span class="stages-region-status-chip">${escapeHtml(status)}<strong>B${highest}</strong></span>
      </button>`;
    })
    .join("");
  const extras = [
    WEEKDAY_STAGES.find((stage) => stage.id === "weekday_skill"),
    ...TRIAL_STAGES,
  ]
    .filter((stage): stage is StageDef => !!stage)
    .map((stage) => {
      const locked = !isStageUnlocked(save, stage.id);
      const cost = stageEnergyCost(stage);
      return `<button type="button" class="dungeon-pick-card${locked ? " is-locked" : ""}" data-core-stage="${stage.id}" ${locked ? "disabled" : ""}>
        <img class="dungeon-pick-art" src="${battleCircleSrc(battleCircleIdForStage(stage))}" width="160" height="160" alt="" draggable="false" />
        <strong class="dungeon-pick-name">${escapeHtml(stage.nameKo)}</strong>
        ${stageDropPreview(stage, { keySets: true })}
        <span class="stage-sortie-cost" aria-hidden="true"><strong>${cost}</strong></span>
      </button>`;
    })
    .join("");
  return `<div class="dungeon-pick-list dungeon-pick-list--cadence">${cards}${extras}</div>`;
}

function renderStagesRegionSheet(region: StagesRegion): string {
  const seasonWins = save.arenaSeasonWins ?? 0;
  const energyNow = Math.floor(save.island.energy);
  const energyMax = save.island.energyMax ?? 100;

  let extras = "";
  if (region.equipWeekly) {
    extras = `<div class="season-panel"><span class="guild-chip">${escapeHtml(t("ui.9cbaf58b88"))}<strong>${equipVaultRemaining(syncEquipVaultWeek(save))}/${EQUIP_VAULT_WEEKLY_LIMIT}</strong></span></div>`;
  }
  if (region.id === "challenge_tower") {
    const synced = syncChallengeTowerMonth(save);
    const floor =
      challengeTowerFloor(synced) + challengeTowerFloor(synced, "hard");
    extras = `<div class="season-panel"><span class="guild-chip">${escapeHtml(t("stages.challengeTowerProgress"))}<strong>${floor}/${CHALLENGE_TOWER_FLOORS * 2}</strong></span></div>`;
  }
  if (region.arena || region.warena) {
    extras = "";
  }

  const mqPin = isMainQuestRegion(region.id)
    ? MAIN_QUEST_PIN_LAYOUT.find((p) => p.id === region.id)
    : null;
  const regionTitle = mqPin
    ? `<span class="stages-pin-num" aria-hidden="true">${mqPin.map}</span>${region.name}`
    : region.name;
  const sheetExtra = [
    region.arena || region.warena ? "stages-region-sheet--pvp" : "",
    region.id === "depth" ||
    region.id === "cadence" ||
    region.id === "challenge_tower" ||
    region.equipWeekly ||
    region.guild
      ? "stages-region-sheet--dungeon"
      : "",
  ]
    .filter(Boolean)
    .join(" ");
  const pvpHero =
    region.arena || region.warena
      ? `<div class="pvp-sheet-hero" aria-hidden="true"><img src="/art/hub/mon-preview-arena-720.webp" width="560" height="200" alt="" draggable="false" /></div>`
      : "";

  let listHtml = `<div class="stage-list stage-list--expedition">${stageButtons(region.stages, { equipWeekly: region.equipWeekly, drops: Boolean(region.equipWeekly) })}</div>`;
  if (region.arena) listHtml = renderArenaRegionBody();
  else if (region.warena) listHtml = renderWarenaRegionBody();
  else if (region.guild) listHtml = renderGuildRaidRegionBody();
  else if (region.id === "depth") listHtml = renderCairosRegionBody();
  else if (region.id === "cadence") listHtml = renderCadenceRegionBody();

  const regionStatusChips = region.arena
    ? `<span class="stages-region-status-chip stages-region-status-chip--ticket" title="${escapeHtml(t("res.arenaTicket"))}">
            <img class="res-ico" src="/art/ui/res/arena-ticket.svg" width="16" height="16" alt="" draggable="false" />
            <strong>${arenaAttacksRemaining(save)}/${ARENA_ATTACKS_DAILY}</strong>
          </span>
          <span class="stages-region-status-chip stages-region-status-chip--rating" title="${escapeHtml(t("ui.arena.rating"))}">
            <strong>${fmtRes(save.arenaRating ?? DEFAULT_ARENA_RATING)}</strong>
          </span>`
    : region.warena
      ? `<span class="stages-region-status-chip stages-region-status-chip--rating" title="${escapeHtml(t("ui.b78477b088"))}">
            <strong>${fmtRes(seasonWins)}</strong>
          </span>`
      : `<span class="stages-region-status-chip stages-region-status-chip--energy" title="${escapeHtml(t("res.energy"))}">
            <img class="res-ico" src="/art/ui/res/energy.svg" width="16" height="16" alt="" draggable="false" />
            <strong>${energyNow}/${energyMax}</strong>
          </span>`;

  const dropBtn =
    regionHasDrops(region) && (region.id !== "depth" || !!stagesDepthDungeon)
      ? `<button type="button" class="stages-region-drop-btn${stagesDropInfoOpen ? " is-on" : ""}" id="btn-region-drop-info" aria-pressed="${stagesDropInfoOpen ? "true" : "false"}">${t("ui.stageDropInfo")}</button>`
      : "";

  const diffMeta =
    STAGE_DIFFICULTIES.find((d) => d.id === stageEntryDiff) ??
    STAGE_DIFFICULTIES[0]!;
  const diffSelect = !regionUsesDifficulty(region)
    ? ""
    : `<label class="stages-region-diff-inline stages-region-diff-inline--sortie">
          <span class="stages-region-diff-label">${t("ui.stageDiff")}</span>
          <select class="stages-region-diff-select stages-region-diff-select--${stageEntryDiff}" id="region-diff-select" aria-label="${t('ui.1a3b3223e1')}" title="${diffMeta.blurb}">
            ${STAGE_DIFFICULTIES.map((d) => {
              const open = regionDifficultyOpen(region, d.id);
              const selected = d.id === stageEntryDiff ? "selected" : "";
              const label = open ? d.labelKo : `${d.labelKo} (${t('ui.956f2f4243')})`;
              return `<option value="${d.id}" ${selected} ${open ? "" : "disabled"}>${label}</option>`;
            }).join("")}
          </select>
        </label>`;

  return `<div class="stages-region-layer" id="stages-region-layer">
    <button type="button" class="stages-region-backdrop" id="btn-region-close" data-core-region-close aria-label="${t('ui.94b7dba159')}"></button>
    <div class="stages-region-sheet stages-region-sheet--card stages-region-sheet--sortie stages-region-sheet--${region.tone} ${sheetExtra}" data-diff="${stageEntryDiff}" role="dialog" aria-modal="true" aria-labelledby="stages-region-title">
      ${modalCloseX(t("ui.94b7dba159"), "btn-region-close")}
      ${pvpHero}
      <header class="stages-region-head stages-region-head--sortie">
        <h2 class="stages-region-title stages-region-title--sortie" id="stages-region-title">${regionTitle}</h2>
        ${diffSelect}
        <div class="stages-region-tools">
          ${dropBtn}
          <div class="stages-region-tools-stats">
            ${regionStatusChips}
          </div>
        </div>
      </header>
      ${extras}
      ${listHtml}
    </div>
    ${renderStageDropInfoModal(region)}
  </div>`;
}
function renderStages(): string {
  const regions = stagesRegions();
  const mqNodes = MAIN_QUEST_PIN_LAYOUT.map(
    (p) =>
      `<span class="stages-mq-node" style="left:${p.x}%;top:${p.y}%" aria-hidden="true"><span class="stages-mq-node-core"></span></span>`,
  ).join("");
  const pins = regions
    .map((r) => {
      const prog = regionProgress(r.stages);
      const open = isStagesRegionOpen(r);
      const active = stagesRegion === r.id;
      const mq = isMainQuestRegion(r.id);
      const onboardPin =
        onboard.step === "stages" && r.id === "mq1"
          ? " is-onboard-focus is-active"
          : onboard.step === "battle" && r.id === "mq1"
            ? " is-onboard-focus"
            : "";
      const pinLayout = mq
        ? MAIN_QUEST_PIN_LAYOUT.find((p) => p.id === r.id)
        : null;
      const mark = mq ? String(pinLayout?.map ?? "") : "";
      // Depth is a hub of three 10-floor dungeons, so a flat cleared/total is noise.
      const sub =
        r.id === "depth"
          ? ""
          : mq
            ? `${prog.cleared}/${STAGES_PER_AREA}`
            : `${prog.cleared}/${prog.total}`;
      const lockMark = open
        ? ""
        : `<span class="stages-pin-lock" aria-hidden="true"><svg viewBox="0 0 24 24" width="14" height="14"><path fill="currentColor" d="M17 9h-1V7a4 4 0 0 0-8 0v2H7a2 2 0 0 0-2 2v8a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2v-8a2 2 0 0 0-2-2zm-6-2a2 2 0 1 1 4 0v2h-4V7zm6 12H7v-8h10v8z"/></svg></span>`;
      const titleNum = mark
        ? `<span class="stages-pin-num" aria-hidden="true">${mark}</span>`
        : "";
      const ariaName = mark ? `${mark} ${r.name}` : r.name;
      return `<button type="button" class="stages-pin ${mq ? "stages-pin--mq" : "stages-pin--side"} stages-pin--${r.tone}${open ? "" : " is-locked"}${active ? " is-active" : ""}${onboardPin}${prog.cleared === prog.total && prog.total > 0 ? " is-cleared" : ""}" style="left:${r.x}%;top:${r.y}%" data-region="${r.id}" data-core-region="${r.id}" aria-label="${ariaName}${open ? "" : ` ${MIDDOT} ${t('ui.b35f488f01')}`}" ${open ? "" : 'data-locked="1"'}>
        <span class="stages-pin-dot" aria-hidden="true">${mq ? `<span class="stages-pin-mark">${mark}</span>` : ""}</span>
        <span class="stages-pin-label">
          <strong>${lockMark}${titleNum}${r.name}</strong>
          ${
            open && !sub
              ? ""
              : `<small>${open ? sub : t('ui.759f762a02')}</small>`
          }
        </span>
      </button>`;
    })
    .join("");
  return `<div class="stages-hub stages-hub--map">
    <div class="stages-viewport" id="stages-viewport">
      <div class="stages-world" id="stages-world" style="transform:translate(${stagesPan.x}px,${stagesPan.y}px)">
        <img
          class="stages-map-img"
          src="/art/stages/stages-world-map.png"
          width="1080"
          height="1920"
          alt=""
          decoding="async"
          draggable="false"
        />
        <div class="stages-map-veil" aria-hidden="true"></div>
        <div class="stages-mq-nodes">${mqNodes}</div>
        <div class="stages-map-pins">${pins}</div>
      </div>
    </div>
    <div id="stages-region-host"></div>
  </div>`;
}

function renderBattleTicker(): string {
  if (!battle) return "";
  // ASCII-safe keyword list (\u escapes) — do not use Hangul regex literals here.
  const keys = [
    t('ui.f4d93d3cf8'),
    t('ui.048b7511df'),
    t('ui.00faa47381'),
    t('ui.fe1fb24836'),
    t('ui.00b2768bcc'),
    t('ui.c1ef178866'),
    t('ui.413147d435'),
    "defeated",
    t('ui.95ca12ad92'),
    t('ui.f3d47aa42f'),
    t('ui.b4d6128261'),
    t('ui.aad8793826'),
    t('ui.0898bd2315'),
    t('ui.bf60bb0a77'),
    t('ui.e36213525e'),
    t('ui.bff20dc3bb'),
    t('ui.c2646fe538'),
    t('ui.85de958b5f'),
    t('ui.06dd3affb3'),
    t('ui.4d67306e14'),
    t('ui.e480e4fefe'),
    t('ui.b89e5dbdd6'),
    t('ui.7311d239fd'),
    t('ui.511fa65e38'),
    t('ui.329b63fdf1'),
    t('ui.d5028d9279'),
  ];
  const lines = battle.log
    .filter((l) => keys.some((k) => l.includes(k)))
    .slice(-3);
  if (!lines.length) {
    return `<div class="battle-ticker muted">${t('ui.0fd080f51d')}</div>`;
  }
  return `<div class="battle-ticker" aria-live="polite">${lines
    .map((l) => `<span>${l}</span>`)
    .join("")}</div>`;
}

/** Lives on #app so combat ticks never remount it. */
function renderBattleAutoSettings(): string {
  const allEnabled = battleAutoOptions.stone && battleAutoOptions.combat;
  const option = (
    id: "stone" | "combat" | "all" | "minimap",
    label: Parameters<typeof t>[0],
    enabled: boolean,
  ) => `<button type="button" class="battle-auto-option${enabled ? " is-on" : ""}" data-auto-option="${id}" role="switch" aria-checked="${enabled}" aria-label="${escapeHtml(t(label))}">
      <span>${escapeHtml(t(label))}</span><i aria-hidden="true"></i>
    </button>`;
  const screenOn = battleSettingsTab === "screen";
  const autoOn = battleSettingsTab === "auto";
  const soundOn = battleSettingsTab === "sound";
  const p = getAudioPrefs();
  const pct = (n: number) => String(Math.round(n * 100));
  const audioRow = (id: "bgm" | "sfx", label: Parameters<typeof t>[0], value: number, enabled: boolean) =>
    `<div class="battle-audio-row">
      <span class="battle-audio-label">${escapeHtml(t(label))}</span>
      <button type="button" class="battle-audio-toggle${enabled ? " is-on" : ""}" data-audio-toggle="${id}" data-no-sfx="1" role="switch" aria-checked="${enabled}">${escapeHtml(enabled ? t("ui.battleAudioOn") : t("ui.battleAudioOff"))}</button>
      <input type="range" min="0" max="100" step="1" value="${pct(value)}" data-audio-range="${id}" data-no-sfx="1" ${enabled ? "" : "disabled"} />
      <span class="battle-audio-val" data-audio-val="${id}">${pct(value)}</span>
    </div>`;
  return `<div class="settings-layer battle-settings-layer battle-auto-settings" id="battle-auto-settings" aria-label="${escapeHtml(t("ui.battleSettings"))}" hidden aria-hidden="true">
    <button type="button" class="settings-backdrop" data-auto-settings-close aria-label="${escapeHtml(t("ui.1a7f31cadb"))}"></button>
    <div class="battle-auto-settings-card" role="dialog" aria-modal="true">
      <div class="battle-auto-settings-head">
        <strong>${escapeHtml(t("ui.battleSettings"))}</strong>
        <button type="button" class="battle-auto-settings-close" data-auto-settings-close aria-label="${escapeHtml(t("ui.1a7f31cadb"))}">&times;</button>
      </div>
      <div class="battle-settings-tabs" role="tablist" aria-label="${escapeHtml(t("ui.battleSettings"))}">
        <button type="button" class="battle-settings-tab${screenOn ? " is-on" : ""}" data-battle-settings-tab="screen" role="tab" aria-selected="${screenOn}">${escapeHtml(t("ui.battleSettingsTabScreen"))}</button>
        <button type="button" class="battle-settings-tab${autoOn ? " is-on" : ""}" data-battle-settings-tab="auto" role="tab" aria-selected="${autoOn}">${escapeHtml(t("ui.battleSettingsTabAuto"))}</button>
        <button type="button" class="battle-settings-tab${soundOn ? " is-on" : ""}" data-battle-settings-tab="sound" role="tab" aria-selected="${soundOn}">${escapeHtml(t("ui.battleSettingsTabSound"))}</button>
      </div>
      <div class="battle-settings-body">
        <div class="battle-settings-panel${screenOn ? "" : " is-hidden"}" data-battle-settings-panel="screen" role="tabpanel"${screenOn ? "" : " hidden"}>
          <div class="battle-auto-options">
            ${option("minimap", "ui.battleMinimap", battleMinimapOn)}
          </div>
        </div>
        <div class="battle-settings-panel${autoOn ? "" : " is-hidden"}" data-battle-settings-panel="auto" role="tabpanel"${autoOn ? "" : " hidden"}>
          <div class="battle-auto-options">
            ${option("stone", "ui.autoStone", battleAutoOptions.stone)}
            ${option("combat", "ui.autoCombat", battleAutoOptions.combat)}
            ${option("all", "ui.autoAll", allEnabled)}
          </div>
        </div>
        <div class="battle-settings-panel${soundOn ? "" : " is-hidden"}" data-battle-settings-panel="sound" role="tabpanel"${soundOn ? "" : " hidden"}>
          ${audioRow("bgm", "settings.audioBgm", p.bgm, !p.bgmMuted)}
          ${audioRow("sfx", "settings.audioSfx", p.sfx, !p.sfxMuted)}
        </div>
      </div>
    </div>
  </div>`;
}

function renderBattle(manaPct: number): string {
  if (!battle || !currentStage) return "";
  const allyUnits = battle.units.filter((u) => u.team === "ally");
  const enemyUnits = battle.units.filter((u) => u.team === "enemy");
  const active = battle.activeUnitId
    ? battle.getUnit(battle.activeUnitId) ?? null
    : null;
  const awaitSkill =
    battle.phase === "await_skill" &&
    active?.team === "ally" &&
    (!autoMode || !battleAutoLive.combat);
  const canPlaceStone =
    battle.phase === "await_stone" &&
    active?.team === "ally" &&
    (!autoMode || !battleAutoLive.stone);

  const showBoardSwitch =
    battle.boards.length > 1 && canPlaceStone;
  const utilRow =
    showBoardSwitch
      ? `<div class="battle-util-row">
        <button type="button" class="secondary board-switch" id="btn-board-switch">${t("ui.bf185333fe")} ${battle.boardLabel === t("ui.8bbc778e36") ? `${ARROW_RIGHT}B` : `${ARROW_RIGHT}A`}</button>
      </div>`
      : "";

  const stageTitle = escapeHtml(currentStage.nameKo);
  const pageLabel = escapeHtml(
    t("ui.battlePage", {
      current: battle.currentWave,
      total: battle.totalWaves,
    }),
  );
  const bossMode = isBossBattleWave(enemyUnits);
  const boss = bossMode ? battleBossUnit(enemyUnits) : null;
  const bossHpPct = boss
    ? Math.round((boss.hp / Math.max(1, boss.stats.hp)) * 100)
    : 0;
  const raidHp = save.raidBossHp ?? RAID_BOSS_MAX_HP;
  const raidPct = RAID_BOSS_MAX_HP ? (raidHp / RAID_BOSS_MAX_HP) * 100 : 0;
  const bossAff = boss ? battleHpAffinityClass(boss) : "";
  const bossEl = boss ? renderBattleUnitElementBadge(boss) : "";
  const bossBar = boss
    ? `<div class="battle-boss-hp${bossAff}">
        ${bossEl}
        <span class="battle-boss-hp-fill" style="width:${bossHpPct}%"></span>
        <strong>${fmtRes(boss.hp)} / ${fmtRes(boss.stats.hp)}</strong>
      </div>${
        currentStage.mode === "guild_raid"
          ? `<div class="battle-raid-hp" title="${escapeHtml(t("ui.guild.raidHp"))}">
        <span class="battle-raid-hp-fill" style="width:${raidPct}%"></span>
        <strong>${fmtRes(raidHp)} / ${fmtRes(RAID_BOSS_MAX_HP)}</strong>
      </div>`
          : ""
      }`
    : "";
  const bossSilhouette =
    bossMode && currentStage.bossArtId
      ? `<div class="battle-boss-silhouette" aria-hidden="true"><img src="/art/battle/circle/${currentStage.bossArtId}.webp" width="280" height="280" alt="" draggable="false" /></div>`
      : "";
  const chaseClass = pageTransitionFx ? ` is-page-${pageTransitionFx}` : "";

  return `<div class="battle-screen battle-screen--enter${
    onboard.step === "battle" && currentStage?.id === ONBOARD_FIRST_STAGE_ID
      ? " is-onboard-rite"
      : ""
  }${currentStage?.bossMonsterId ? " battle-screen--boss-stage" : ""}${bossMode ? " battle-screen--boss" : ""}${chaseClass}" data-bg="${battleBgIdForStage(currentStage)}">
    ${battleSkyHtml(currentStage)}
    <header class="battle-chrome">
      ${renderBoardMiniCol()}
      <div class="battle-stage-pill" title="${stageTitle}">
        <strong class="battle-stage-name">${stageTitle}</strong>
        <span class="battle-page">${pageLabel}</span>
      </div>
    </header>
    <div class="battle-layout battle-layout--framed battle-layout--stage${canPlaceStone ? " is-stone-pick" : ""}${awaitSkill ? " is-skill-pick" : ""}${stoneSummonFx ? " is-stone-summoning" : ""}">
    <div class="dmg-layer" aria-hidden="true">${renderDmgLayer()}</div>
    <div class="skill-fx-layer" aria-hidden="true"></div>
    ${
      waveBannerText
        ? `<div class="battle-wave-banner" aria-live="polite"><span>${escapeHtml(
            t("ui.battlePage", {
              current: battle.currentWave,
              total: battle.totalWaves,
            }),
          )}</span></div>`
        : ""
    }
    <div class="battle-lane enemy${waveEnterIds.size ? " is-wave-spawning" : ""}">
      ${bossSilhouette}
      ${bossBar}
      ${renderBattleFront(enemyUnits, "enemy", { targetable: awaitSkill })}
    </div>
    <div class="board-wrap board-wrap--stage${canPlaceStone ? " is-live" : ""}">
      ${renderBoardTabs()}${renderBoard()}${renderCaptureShop()}
    </div>
    <div class="battle-lane ally">
      ${renderBattleFront(allyUnits, "ally")}
    </div>
    ${renderStonePickLayer()}
    ${renderStoneResultLayer()}
    ${utilRow}
    <div class="battle-hud battle-hud--stage">
      ${navBackBtn({ id: "btn-back", label: t('ui.1a7f31cadb') })}
      <div class="battle-hud-actions">
        ${battleSkipAllowedForStage(currentStage) ? `<button type="button" class="secondary${battleSkipReady ? " is-ready" : ""}" id="btn-battle-skip"${battleSkipReady ? "" : " disabled"}>${escapeHtml(t("ui.battleSkip"))}</button>` : ""}
        <button type="button" class="secondary" id="btn-speed">x${battleSpeed}</button>
        <button type="button" class="secondary battle-auto-settings-trigger${battleAutoSettingsOpen ? " is-open" : ""}" id="btn-auto-settings" aria-expanded="${battleAutoSettingsOpen}" aria-controls="battle-auto-settings" aria-label="${escapeHtml(t("ui.battleSettings"))}">&#9881;</button>
        <button type="button" id="btn-auto-toggle" class="${autoMode ? "auto-on" : ""}">${autoMode ? "AUTO ON" : "AUTO"}</button>
      </div>
    </div>
  </div>
  </div>`;
}

/** Snapshot unit art nodes (incl. spine hosts) before a soft battle DOM rebuild. */
function captureBattleArtMap(root: ParentNode): Map<string, HTMLElement> {
  const map = new Map<string, HTMLElement>();
  root.querySelectorAll<HTMLElement>(".battle-unit[data-unit]").forEach((unit) => {
    const id = unit.dataset.unit;
    const art = unit.querySelector<HTMLElement>(".battle-unit-art");
    if (id && art) map.set(id, art);
  });
  return map;
}

/** Reattach preserved art when src matches so images/spine do not remount. */
function restoreBattleArt(
  root: ParentNode,
  arts: Map<string, HTMLElement>,
): void {
  root.querySelectorAll<HTMLElement>(".battle-unit[data-unit]").forEach((unit) => {
    const id = unit.dataset.unit;
    if (!id) return;
    const prev = arts.get(id);
    const next = unit.querySelector<HTMLElement>(".battle-unit-art");
    if (!prev || !next || prev === next) return;
    const prevSrc = prev.querySelector("img")?.getAttribute("src");
    const nextSrc = next.querySelector("img")?.getAttribute("src");
    if (prevSrc && prevSrc === nextSrc) next.replaceWith(prev);
  });
}

/**
 * Patch the live battle screen in place (no app.innerHTML wipe).
 * Preserves sky BG, mini board, and unit art/spine so combat does not flash.
 */
function refreshBattleView(): boolean {
  if (view !== "battle" || !battle || !currentStage) return false;
  const screen = app.querySelector<HTMLElement>(".battle-screen");
  if (!screen) return false;

  const allyMana = battle.allySummoner;
  const manaPct = Math.round((allyMana.mana / allyMana.manaMax) * 100);
  const arts = captureBattleArtMap(screen);
  const sky = screen.querySelector<HTMLElement>(".battle-sky");
  const chrome = screen.querySelector<HTMLElement>(".battle-chrome");
  const layout = screen.querySelector<HTMLElement>(".battle-layout");

  const wrap = document.createElement("div");
  wrap.innerHTML = renderBattle(manaPct);
  const next = wrap.firstElementChild as HTMLElement | null;
  if (!next) return false;

  // Drop enter animation on subsequent soft updates
  next.classList.remove("battle-screen--enter");
  screen.classList.remove("battle-screen--enter");
  const nextBg = next.getAttribute("data-bg");
  if (nextBg) screen.setAttribute("data-bg", nextBg);
  else screen.removeAttribute("data-bg");
  screen.classList.toggle(
    "battle-screen--boss",
    next.classList.contains("battle-screen--boss"),
  );
  screen.classList.toggle(
    "battle-screen--boss-stage",
    next.classList.contains("battle-screen--boss-stage"),
  );
  for (const name of [...screen.classList]) {
    if (name.startsWith("is-page-")) screen.classList.remove(name);
  }
  for (const name of next.classList) {
    if (name.startsWith("is-page-")) screen.classList.add(name);
  }

  // Keep sky + mini in the live document. Parking them in the detached
  // template (then replaceChildren) makes WebView dump decoded images.
  next.querySelector(".battle-sky")?.remove();

  const nextChrome = next.querySelector<HTMLElement>(".battle-chrome");
  if (nextChrome) {
    if (chrome) patchBattleChrome(chrome, nextChrome);
    else if (sky) sky.after(nextChrome);
    else screen.prepend(nextChrome);
  }

  const nextLayout = next.querySelector<HTMLElement>(".battle-layout");
  if (nextLayout) {
    if (layout) patchBattleLayout(layout, nextLayout);
    else screen.appendChild(nextLayout);
  }

  restoreBattleArt(screen, arts);
  bindBattleInteractive();
  mountUnitAnimHooks(screen);
  refreshDmgLayer();
  restoreBattleAutoSettingsIfOpen();
  syncBoardMini();
  return true;
}

/** Taps on the large flat pick grid place a stone; the map circle absorbs. */
function bindStonePickTaps(): void {
  const hit = app.querySelector<HTMLElement>(".stone-pick-hit");
  if (!hit) return;
  hit.addEventListener("pointerup", (ev) => {
    if (ev.button != null && ev.button !== 0) return;
    const layer = hit.closest(".stone-pick-layer");
    if (layer instanceof HTMLElement && layer.hidden) return;
    const target = ev.target;
    if (!(target instanceof Element)) return;
    const btn = target.closest<HTMLButtonElement>("button.cell.is-placeable");
    if (!btn || btn.disabled || !hit.contains(btn)) return;
    ev.preventDefault();
    onCellClick(Number(btn.dataset.x), Number(btn.dataset.y));
  });
}

function leaveBattleOrResultScreen(): void {
  viewHistoryLock = true;
  autoMode = false;
  battleAutoSettingsOpen = false;
  removeBattleAutoSettingsLayer();
  stoneResultSheetOpen = false;
  stoneResultSheetReport = null;
  stoneResultSheetResolve?.();
  stoneResultSheetResolve = null;
  stonePickHelpOpen = false;
  stonePickPlaceCued = false;
  findStonePickHelpLayer()?.remove();
  battleSkillInfo = null;
  clearBattleSkillLongPress();
  battleSkillSuppressClick = false;
  findBattleSkillInfoLayer()?.remove();
  clearAutoTimer();
  clearBattleSkipTimer();
  battleSkipTimeReady = false;
  battleSkipReady = false;
  battleSkipSeq += 1;
  if (battle?.finishReason) grantRewardIfNeeded();
  if (view === "result") {
    leaveResultView("stages");
    lastTrackedView = view;
    viewHistoryLock = false;
    return;
  }
  battle = null;
  currentStage = null;
  lastReward = null;
  lastScrollGain = 0;
  lastScrollPremiumGain = 0;
  lastScrollLegendGain = 0;
  dmgFloats = [];
  clearBattleSkillSelection();
  view = "stages";
  render();
  lastTrackedView = view;
  viewHistoryLock = false;
}

/** Rebind combat controls after a soft battle DOM patch. */
function bindBattleInteractive(): void {
  app.querySelector("#btn-board-switch")?.addEventListener("click", () => {
    if (!battle) return;
    if (!battle.switchBoard(t("ui.a9034f7e3d"))) return;
    refreshLegal();
    render();
  });

  app.querySelectorAll<HTMLButtonElement>("[data-board-tab]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (!battle || battle.boards.length < 2) return;
      const idx = Number(btn.dataset.boardTab);
      if (!Number.isFinite(idx) || idx === battle.activeBoardIndex) return;
      if (!battle.switchBoard(t("ui.a9034f7e3d"))) return;
      refreshLegal();
      render();
    });
  });

  app.querySelectorAll<HTMLButtonElement>("[data-shop]").forEach((btn) => {
    btn.addEventListener("click", () => {
      if (!battle) return;
      const choice = btn.dataset.shop as CaptureShopChoice;
      if (!battle.chooseCaptureShop(choice)) return;
      void resolveCombatUntilAllyInput();
    });
  });

  const boardHit = app.querySelector<HTMLElement>(".board-frame .board-hit");
  if (boardHit) {
    boardHit.addEventListener("pointerup", (ev) => {
      if (ev.button != null && ev.button !== 0) return;
      const t = ev.target;
      if (!(t instanceof Element)) return;
      const btn = t.closest<HTMLButtonElement>("button.cell.is-placeable");
      if (!btn || btn.disabled || !boardHit.contains(btn)) return;
      onCellClick(Number(btn.dataset.x), Number(btn.dataset.y));
    });
  } else {
    app.querySelectorAll<HTMLButtonElement>(".board-frame .board .cell").forEach((btn) => {
      btn.addEventListener("click", () => {
        onCellClick(Number(btn.dataset.x), Number(btn.dataset.y));
      });
    });
  }

  bindStonePickTaps();
  bindStonePickChrome();
  bindBattleSkillInspect();
  syncActiveUnitSkillPosition();

  app.querySelectorAll<HTMLButtonElement>(".suggest-chip").forEach((btn) => {
    btn.addEventListener("click", () => {
      onCellClick(Number(btn.dataset.sgx), Number(btn.dataset.sgy));
    });
  });

  app.querySelectorAll<HTMLButtonElement>("[data-target]").forEach((btn) => {
    btn.addEventListener("click", () => {
      selectedTargetId = btn.dataset.target ?? null;
      if (
        !battle ||
        battle.phase !== "await_skill" ||
        (autoMode && battleAutoLive.combat) ||
        battleFxBusy
      ) {
        render();
        return;
      }
      const unit = battle.activeUnitId
        ? battle.getUnit(battle.activeUnitId)
        : null;
      if (!unit || unit.team !== "ally") {
        render();
        return;
      }
      if (selectedSummonerSkill && summonerSkillNeedsEnemyTarget(selectedSummonerSkill, unit)) {
        castSkill(selectedSummonerSkill, selectedTargetId ?? undefined);
        return;
      }
      if (selectedSkillIndex != null) {
        castSkill(selectedSkillIndex, selectedTargetId ?? undefined);
        return;
      }
      flash(t("ui.battlePickSkill"));
      render();
    });
  });

  app.querySelectorAll<HTMLButtonElement>("[data-skill]").forEach((btn) => {
    btn.addEventListener("click", (ev) => {
      ev.stopPropagation();
      if (battleSkillSuppressClick) {
        battleSkillSuppressClick = false;
        ev.preventDefault();
        return;
      }
      if (
        !battle ||
        battle.phase !== "await_skill" ||
        (autoMode && battleAutoLive.combat) ||
        battleFxBusy ||
        skillBtnIsBlocked(btn)
      )
        return;
      const idx = Number(btn.dataset.skill);
      if (!Number.isFinite(idx)) return;
      const active = battle.activeUnitId
        ? battle.getUnit(battle.activeUnitId)
        : null;
      if (!active || !battle.canUseSkill(active, idx)) return;
      selectedSummonerSkill = null;
      selectedSkillIndex = selectedSkillIndex === idx ? null : idx;
      render();
    });
  });

  app
    .querySelectorAll<HTMLButtonElement>("[data-summoner-skill]")
    .forEach((btn) => {
      btn.addEventListener("click", (ev) => {
        ev.stopPropagation();
        if (battleSkillSuppressClick) {
          battleSkillSuppressClick = false;
          ev.preventDefault();
          return;
        }
        if (
          !battle ||
          battle.phase !== "await_skill" ||
          (autoMode && battleAutoLive.combat) ||
          battleFxBusy ||
          skillBtnIsBlocked(btn)
        )
          return;
        const id = btn.dataset.summonerSkill;
        if (!id) return;
        selectedSkillIndex = null;
        const active = battle.activeUnitId
          ? battle.getUnit(battle.activeUnitId)
          : null;
        if (summonerSkillNeedsEnemyTarget(id, active)) {
          selectedSummonerSkill =
            selectedSummonerSkill === id ? null : id;
          render();
          return;
        }
        // Buff / board skills: cast immediately (no enemy tap).
        selectedSummonerSkill = id;
        castSkill(id);
      });
    });

  app.querySelector("#btn-speed")?.addEventListener("click", () => {
    battleSpeed = battleSpeed === 1 ? 2 : battleSpeed === 2 ? 3 : 1;
    render();
    if (autoMode) scheduleAuto();
  });

  bindStoneResultSheet();
  bindBattleAutoSettings();

  app.querySelector("#btn-battle-skip")?.addEventListener("click", () => {
    skipBattleToResult();
  });

  app.querySelector("#btn-auto-toggle")?.addEventListener("click", () => {
    if (!battle || battle.finishReason) return;
    setBattleAutoMode(!autoMode);
    render();
  });

  app.querySelector("#btn-back")?.addEventListener("click", () => {
    leaveBattleOrResultScreen();
  });
}

/** Keep the active unit's action strip within the visible viewport. */
function syncActiveUnitSkillPosition(): void {
  requestAnimationFrame(() => {
    const skills = app.querySelector<HTMLElement>(
      ".battle-unit.active .battle-unit-skills",
    );
    if (!skills) return;
    skills.style.removeProperty("--battle-skill-shift");
    const rect = skills.getBoundingClientRect();
    const inset = 6;
    const shift =
      rect.left < inset
        ? inset - rect.left
        : rect.right > window.innerWidth - inset
          ? window.innerWidth - inset - rect.right
          : 0;
    skills.style.setProperty("--battle-skill-shift", `${Math.round(shift)}px`);
  });
}

function bindAuth(): void {
  bindAuthPwaInstall();

  app.querySelectorAll<HTMLAnchorElement>("[data-auth-legal]").forEach((a) => {
    a.addEventListener("click", (ev) => {
      ev.preventDefault();
      const kind = a.dataset.authLegal;
      if (kind === "privacy" || kind === "terms") {
        authUi.pane = kind;
        history.replaceState(null, "", `#${kind}`);
        render();
      }
    });
  });

  app.querySelector("#auth-open-login")?.addEventListener("click", () => {
    authUi.pane = "login";
    render();
  });


  app.querySelector("#auth-start")?.addEventListener("click", () => {
    void startGameFromAuth();
  });

  app.querySelector("#auth-logout")?.addEventListener("click", () => {
    void logout();
  });

  app.querySelector("#auth-demo")?.addEventListener("click", () => {
    void (async () => {
      const res = await apiJson<{ user: SessionUser }>("/api/auth/demo", {
        method: "POST",
        body: "{}",
      });
      if (res?.user) {
        await enterWithUser(res.user, { demo: true, enterGame: true });
        return;
      }
      await enterWithUser(
        { id: "local-demo", email: null, kind: "demo" },
        { demo: true, enterGame: true },
      );
    })();
  });

  app.querySelector("#auth-register")?.addEventListener("click", () => {
    authUi.pane = "register";
    render();
  });
  app.querySelector("#auth-back")?.addEventListener("click", () => {
    authUi.pane = "gate";
    if (location.hash === "#privacy" || location.hash === "#terms") {
      history.replaceState(null, "", location.pathname + location.search);
    }
    render();
  });

  app.querySelector("#auth-form")?.addEventListener("submit", (ev) => {
    ev.preventDefault();
    const form = ev.target as HTMLFormElement;
    const fd = new FormData(form);
    const email = String(fd.get("email") ?? "").trim();
    const password = String(fd.get("password") ?? "");
    const saveId = fd.get("saveId") === "on";
    const autoLogin = fd.get("autoLogin") === "on";
    const path =
      authUi.pane === "register" ? "/api/auth/register" : "/api/auth/login";

    if (authUi.pane === "login") {
      writeAuthPrefs({
        saveId,
        autoLogin,
        savedEmail: saveId ? email : "",
      });
    }

    void (async () => {
      try {
        const res = await fetch(apiUrl(path), {
          method: "POST",
          credentials: "include",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ email, password }),
        });
        const body = (await res.json().catch(() => ({}))) as {
          user?: SessionUser;
          error?: string;
        };
        if (!res.ok || !body.user) {
          flash(
            body.error === "email_taken"
        ? t('ui.0b00025fb4')
              : body.error === "invalid_credentials"
                ? t('ui.0e5bf793ef')
                : t('ui.c17466f9ed'),
          );
          return;
        }
        const isRegister = authUi.pane === "register";
        const enterGame = isRegister ? true : readAuthPrefs().autoLogin;
        await enterWithUser(body.user, {
          enterGame,
          fresh: isRegister,
        });
      } catch {
    flash(t('ui.b72f5a4752'));
      }
    })();
  });
}

function islandOriginPx(world: HTMLElement): { ox: number; oy: number } {
  return {
    ox: world.offsetWidth * ISLAND_TRANSFORM_ORIGIN.x,
    oy: world.offsetHeight * ISLAND_TRANSFORM_ORIGIN.y,
  };
}

function applyIslandPan(): void {
  const world = app.querySelector<HTMLElement>("#island-world");
  if (world) {
    world.style.setProperty("--island-oversize", String(ISLAND_WORLD_OVERSIZE));
    world.style.setProperty("--island-zoom", islandZoom.toFixed(4));
    world.style.transform = `translate3d(${islandPan.x}px,${islandPan.y}px,0) rotateX(${ISLAND_ROTATE_X_DEG}deg) scale(${ISLAND_BASE_SCALE})`;
  }
}

function clampIslandPan(viewport: HTMLElement, world: HTMLElement): void {
  const s = ISLAND_BASE_SCALE;
  const W = world.offsetWidth;
  const H = world.offsetHeight;
  if (W <= 0 || H <= 0) return;
  const { ox, oy } = islandOriginPx(world);
  const vw = viewport.clientWidth;
  const vh = viewport.clientHeight;
  /* Hard edge clamp: never pan past the bitmap. If the world is smaller than
     the viewport, center it. */
  const maxX = -ox * (1 - s);
  const minX = vw - W * s - ox * (1 - s);
  const maxY = -oy * (1 - s);
  const minY = vh - H * s - oy * (1 - s);
  if (minX > maxX) {
    islandPan.x = (vw - W * s) / 2 - ox * (1 - s);
  } else {
    islandPan.x = Math.min(maxX, Math.max(minX, islandPan.x));
  }
  if (minY > maxY) {
    islandPan.y = (vh - H * s) / 2 - oy * (1 - s);
  } else {
    islandPan.y = Math.min(maxY, Math.max(minY, islandPan.y));
  }
}

/** Frame the island camera on a building spot (percent coords on the world map). */
function focusIslandSpot(spotId: string, _opts?: { zoomMul?: number }): void {
  const viewport = app.querySelector<HTMLElement>("#island-viewport");
  const world = app.querySelector<HTMLElement>("#island-world");
  if (!viewport || !world || world.offsetWidth <= 0) return;

  // Zoom stays locked; only pan so the guided building sits in view.
  islandZoom = 1;
  applyIslandPan();

  const W = world.offsetWidth;
  const H = world.offsetHeight;
  if (W <= 0 || H <= 0) return;
  const pos = resolveIslandSpotPos(spotId, 50, 50);
  const fx = Math.max(0.05, Math.min(0.95, pos.x / 100));
  const fy = Math.max(0.05, Math.min(0.95, pos.y / 100));
  const s = ISLAND_BASE_SCALE;
  const { ox, oy } = islandOriginPx(world);
  const vw = viewport.clientWidth;
  const vh = viewport.clientHeight;
  // Bias slightly upward so the spot sits above the objective chip / tabs.
  const targetX = vw * 0.5;
  const targetY = vh * 0.42;
  islandPan.x = targetX - fx * W * s - ox * (1 - s);
  islandPan.y = targetY - fy * H * s - oy * (1 - s);
  islandPanCentered = true;
  clampIslandPan(viewport, world);
  applyIslandPan();
}

/** Once per onboard step, pull the island camera to the guided building. */
function maybeFocusOnboardIslandSpot(): void {
  if (view !== "home" || islandLayoutEdit || onboardWelcomeOpen || nicknameSetupOpen) return;
  if (onboard.step === "done") return;
  const spotId = onboardFocusSpotId(onboard.step);
  if (!spotId) return;
  if (onboardIslandFocusStep === onboard.step) return;
  onboardIslandFocusStep = onboard.step;
  const run = (): void => focusIslandSpot(spotId);
  // After bindIslandPan's initial clamp rAF so we do not get recentered away.
  requestAnimationFrame(() => requestAnimationFrame(run));
}

function bindIslandPan(): void {
  const viewport = app.querySelector<HTMLElement>("#island-viewport");
  const world = app.querySelector<HTMLElement>("#island-world");
  if (!viewport || !world) return;

  islandActivePointers.clear();
  if (islandCoverFitApplied !== ISLAND_COVER_FIT_VERSION) {
    islandCoverFitApplied = ISLAND_COVER_FIT_VERSION;
    islandPanCentered = false;
    islandZoom = 1;
  }
  islandZoom = 1;
  applyIslandPan();

  const finishClamp = () => {
    islandZoom = 1;
    if (!islandPanCentered && world.offsetWidth > 0) {
      const s = ISLAND_BASE_SCALE;
      const { ox, oy } = islandOriginPx(world);
      islandPan.x = (viewport.clientWidth - world.offsetWidth * s) / 2 - ox * (1 - s);
      islandPan.y =
        (viewport.clientHeight - world.offsetHeight * s) / 2 - oy * (1 - s);
      islandPanCentered = true;
    }
    clampIslandPan(viewport, world);
    applyIslandPan();
  };
  finishClamp();
  requestAnimationFrame(finishClamp);
  const mapImg = world.querySelector<HTMLImageElement>(".island-map-img");
  if (mapImg && !mapImg.complete) {
    mapImg.addEventListener("load", finishClamp, { once: true });
  }

  // Pan only — wheel / pinch zoom intentionally disabled.
  viewport.addEventListener(
    "wheel",
    (ev) => {
      ev.preventDefault();
    },
    { passive: false },
  );

  viewport.addEventListener("pointerdown", (ev) => {
    if (ev.button !== 0) return;
    islandActivePointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });

    if (islandActivePointers.size >= 2) {
      // Ignore multi-touch zoom; keep current pan gesture cancelled.
      islandPanDrag = null;
      clearIslandLongPress();
      viewport.setAttribute("data-pan-moved", "1");
      try {
        viewport.setPointerCapture(ev.pointerId);
      } catch {
        /* ignore */
      }
      return;
    }

    const onSpot = (ev.target as HTMLElement | null)?.closest?.("[data-b]");
    if (islandLayoutEdit && onSpot) return;
    if (onSpot && !islandLayoutEdit) {
      // Long-press handler owns the gesture until cancelled.
      return;
    }
    islandPanDrag = {
      pointerId: ev.pointerId,
      startX: ev.clientX,
      startY: ev.clientY,
      origX: islandPan.x,
      origY: islandPan.y,
      moved: false,
    };
    try {
      viewport.setPointerCapture(ev.pointerId);
    } catch {
      /* ignore */
    }
  });

  viewport.addEventListener("pointermove", (ev) => {
    if (islandActivePointers.has(ev.pointerId)) {
      islandActivePointers.set(ev.pointerId, { x: ev.clientX, y: ev.clientY });
    }

    if (islandActivePointers.size >= 2) {
      return;
    }

    if (!islandPanDrag || islandPanDrag.pointerId !== ev.pointerId) return;
    const dx = ev.clientX - islandPanDrag.startX;
    const dy = ev.clientY - islandPanDrag.startY;
    if (Math.hypot(dx, dy) > 8) islandPanDrag.moved = true;
    islandPan.x = islandPanDrag.origX + dx;
    islandPan.y = islandPanDrag.origY + dy;
    clampIslandPan(viewport, world);
    applyIslandPan();
  });

  const endDrag = (ev: PointerEvent) => {
    islandActivePointers.delete(ev.pointerId);
    if (islandActivePointers.size === 0) {
      queueMicrotask(() => viewport.removeAttribute("data-pan-moved"));
    }

    if (!islandPanDrag || islandPanDrag.pointerId !== ev.pointerId) return;
    const moved = islandPanDrag.moved;
    islandPanDrag = null;
    if (moved) {
      viewport.setAttribute("data-pan-moved", "1");
      queueMicrotask(() => viewport.removeAttribute("data-pan-moved"));
    }
  };
  viewport.addEventListener("pointerup", endDrag);
  viewport.addEventListener("pointercancel", endDrag);
}

function applyStagesPan(): void {
  const world = app.querySelector<HTMLElement>("#stages-world");
  if (world) {
    world.style.transform = `translate(${stagesPan.x}px, ${stagesPan.y}px)`;
  }
}

/**
 * Size the pannable world to the atlas aspect ratio so pin left%/top% map 1:1
 * onto stages-world-map.png on every device (no object-fit cover crop drift).
 */
function sizeStagesWorld(viewport: HTMLElement, world: HTMLElement): void {
  const vw = viewport.clientWidth;
  const vh = viewport.clientHeight;
  if (vw <= 0 || vh <= 0) return;
  let worldH = Math.max(
    vh * STAGES_WORLD_OVERSCAN,
    (vw * STAGES_WORLD_OVERSCAN) / STAGES_MAP_ASPECT,
  );
  let worldW = worldH * STAGES_MAP_ASPECT;
  if (worldW < vw * 1.08) {
    worldW = vw * STAGES_WORLD_OVERSCAN;
    worldH = worldW / STAGES_MAP_ASPECT;
  }
  if (worldH < vh * 1.08) {
    worldH = vh * STAGES_WORLD_OVERSCAN;
    worldW = worldH * STAGES_MAP_ASPECT;
  }
  world.style.width = `${Math.round(worldW)}px`;
  world.style.height = `${Math.round(worldH)}px`;
}

function clampStagesPan(viewport: HTMLElement, world: HTMLElement): void {
  const minX = Math.min(0, viewport.clientWidth - world.offsetWidth);
  const minY = Math.min(0, viewport.clientHeight - world.offsetHeight);
  stagesPan.x = Math.min(0, Math.max(minX, stagesPan.x));
  stagesPan.y = Math.min(0, Math.max(minY, stagesPan.y));
}

/** Frame the stages atlas so a region pin sits in the readable sweet spot. */
function focusStagesRegion(regionId: string): void {
  const viewport = app.querySelector<HTMLElement>("#stages-viewport");
  const world = app.querySelector<HTMLElement>("#stages-world");
  if (!viewport || !world) return;
  sizeStagesWorld(viewport, world);
  const W = world.offsetWidth;
  const H = world.offsetHeight;
  if (W <= 0 || H <= 0) return;
  const pin =
    MAIN_QUEST_PIN_LAYOUT.find((p) => p.id === regionId) ??
    stagesRegions().find((r) => r.id === regionId);
  if (!pin) return;
  const fx = Math.max(0.05, Math.min(0.95, pin.x / 100));
  const fy = Math.max(0.05, Math.min(0.95, pin.y / 100));
  const vw = viewport.clientWidth;
  const vh = viewport.clientHeight;
  // Keep the pin above the region sheet / objective chip.
  const targetX = vw * 0.5;
  const targetY = vh * (stagesRegion ? 0.32 : 0.48);
  stagesPan.x = targetX - fx * W;
  stagesPan.y = targetY - fy * H;
  stagesPanCentered = true;
  clampStagesPan(viewport, world);
  applyStagesPan();
}

/** Once per onboard stages/battle step: frame mq1, open sheet, and prep 1-1. */
function maybeGuideOnboardStages(): void {
  if (view !== "stages") return;
  if (onboard.step !== "stages" && onboard.step !== "battle") return;
  if (onboardStagesFocusStep === onboard.step) return;
  const guidedStep = onboard.step;
  onboardStagesFocusStep = guidedStep;
  const run = (): void => {
    focusStagesRegion("mq1");
    if (guidedStep === "stages") {
      if (stagesRegion !== "mq1" || stageEntryId) {
        stagesRegion = "mq1";
        stageEntryId = null;
        patchOnboard({ openedStages: true, openedRegion: true });
        // patch may advance to battle and clear the focus token — reclaim it.
        onboardStagesFocusStep = onboard.step;
        applyStagesRegionOpen();
        focusStagesRegion("mq1");
      }
      return;
    }
    // battle: open Moonveil + first-stage prep once
    stagesRegion = "mq1";
    const stage = getStage(ONBOARD_FIRST_STAGE_ID);
    if (stage && stageEntryId !== stage.id) {
      openStagePrep(stage);
      onboardStagesFocusStep = onboard.step;
      focusStagesRegion("mq1");
      return;
    }
    applyStagesRegionOpen();
    focusStagesRegion("mq1");
  };
  requestAnimationFrame(() => requestAnimationFrame(run));
}

function bindStagesPan(): void {
  const viewport = app.querySelector<HTMLElement>("#stages-viewport");
  const world = app.querySelector<HTMLElement>("#stages-world");
  if (!viewport || !world) return;

  const finishClamp = () => {
    sizeStagesWorld(viewport, world);
    if (stagesMapFitApplied !== STAGES_MAP_FIT_VERSION) {
      stagesPanCentered = false;
      stagesMapFitApplied = STAGES_MAP_FIT_VERSION;
    }
    if (!stagesPanCentered && world.offsetWidth > 0) {
      // Bias toward the MQ corridor start (lower-center of the atlas).
      stagesPan.x = (viewport.clientWidth - world.offsetWidth) * 0.42;
      stagesPan.y = (viewport.clientHeight - world.offsetHeight) * 0.72;
      stagesPanCentered = true;
    }
    clampStagesPan(viewport, world);
    applyStagesPan();
  };
  finishClamp();
  requestAnimationFrame(finishClamp);

  stagesWorldResizeObs?.disconnect();
  stagesWorldResizeObs = new ResizeObserver(() => {
    sizeStagesWorld(viewport, world);
    clampStagesPan(viewport, world);
    applyStagesPan();
  });
  stagesWorldResizeObs.observe(viewport);

  viewport.addEventListener("pointerdown", (ev) => {
    if (ev.button !== 0) return;
    const target = ev.target as HTMLElement | null;
    if (target?.closest?.(".stages-region-layer")) return;
    if (target?.closest?.("[data-core-region]")) return;
    stagesPanDrag = {
      pointerId: ev.pointerId,
      startX: ev.clientX,
      startY: ev.clientY,
      origX: stagesPan.x,
      origY: stagesPan.y,
      moved: false,
    };
    try {
      viewport.setPointerCapture(ev.pointerId);
    } catch {
      /* ignore */
    }
  });

  viewport.addEventListener("pointermove", (ev) => {
    if (!stagesPanDrag || stagesPanDrag.pointerId !== ev.pointerId) return;
    const dx = ev.clientX - stagesPanDrag.startX;
    const dy = ev.clientY - stagesPanDrag.startY;
    if (Math.hypot(dx, dy) > 8) stagesPanDrag.moved = true;
    stagesPan.x = stagesPanDrag.origX + dx;
    stagesPan.y = stagesPanDrag.origY + dy;
    clampStagesPan(viewport, world);
    applyStagesPan();
  });

  const endDrag = (ev: PointerEvent) => {
    if (!stagesPanDrag || stagesPanDrag.pointerId !== ev.pointerId) return;
    const moved = stagesPanDrag.moved;
    stagesPanDrag = null;
    if (moved) {
      viewport.setAttribute("data-pan-moved", "1");
      queueMicrotask(() => viewport.removeAttribute("data-pan-moved"));
    }
  };
  viewport.addEventListener("pointerup", endDrag);
  viewport.addEventListener("pointercancel", endDrag);
}

function clearIslandLongPress(): void {
  if (islandLongPress) {
    clearTimeout(islandLongPress.timer);
    islandLongPress = null;
  }
}

function bindIslandLayoutEdit(): void {
  const viewport = app.querySelector<HTMLElement>("#island-viewport");
  const world = app.querySelector<HTMLElement>("#island-world");

  app.querySelector("#btn-island-layout-edit")?.addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    if (islandLayoutEdit) return;
    setIslandSpotMenu(null);
    enterIslandLayoutEdit();
  });
  app.querySelector("#btn-island-layout-done")?.addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    exitIslandLayoutEdit(true);
  });
  app.querySelector("#btn-island-layout-reset")?.addEventListener("click", (ev) => {
    ev.preventDefault();
    ev.stopPropagation();
    islandLayoutDraft = { ...ISLAND_LAYOUT_DEFAULT };
    writeIslandLayout(islandLayoutDraft);
    flash(t('ui.f88240ee56'));
    render();
  });

  if (!viewport || !world) return;
  // Soft island re-use: keep existing long-press listeners on the preserved DOM.
  if (preserveIslandDom && !islandLayoutEdit) return;

  app.querySelectorAll<HTMLElement>("[data-b]").forEach((btn) => {
    btn.addEventListener("pointerdown", (ev) => {
      if (ev.button !== 0) return;
      const id = btn.dataset.b;
      if (!id) return;

      if (islandLayoutEdit) {
        ev.preventDefault();
        ev.stopPropagation();
        islandPanDrag = null;
        clearIslandLongPress();
        islandSpotDrag = { id, pointerId: ev.pointerId };
        viewport.classList.add("is-spot-dragging");
        app.querySelectorAll<HTMLElement>("[data-b]").forEach((el) => {
          el.classList.toggle("is-layout-focus", el.dataset.b === id);
          el.classList.toggle("is-dragging", el.dataset.b === id);
        });
        try {
          btn.setPointerCapture(ev.pointerId);
        } catch {
          /* ignore */
        }
        const startPct = clientToIslandPct(ev.clientX, ev.clientY, world);
        updateIslandDropTarget(id, startPct.x, startPct.y);
        return;
      }

      // Long-press a building to enter layout edit (also available via side button).
      clearIslandLongPress();
      islandLongPress = {
        id,
        pointerId: ev.pointerId,
        startX: ev.clientX,
        startY: ev.clientY,
        timer: setTimeout(() => {
          if (!islandLongPress || islandLongPress.id !== id) return;
          islandLongPress = null;
          islandPanDrag = null;
          try {
            navigator.vibrate?.(24);
          } catch {
            /* ignore */
          }
          setIslandSpotMenu(null);
          enterIslandLayoutEdit(id);
        }, 520),
      };
    });

    btn.addEventListener("pointermove", (ev) => {
      if (
        islandLongPress &&
        islandLongPress.pointerId === ev.pointerId &&
        Math.hypot(ev.clientX - islandLongPress.startX, ev.clientY - islandLongPress.startY) > 12
      ) {
        clearIslandLongPress();
        // Hand off to pan.
        islandPanDrag = {
          pointerId: ev.pointerId,
          startX: ev.clientX,
          startY: ev.clientY,
          origX: islandPan.x,
          origY: islandPan.y,
          moved: true,
        };
        try {
          viewport.setPointerCapture(ev.pointerId);
        } catch {
          /* ignore */
        }
        return;
      }

      if (!islandLayoutEdit) return;
      if (!islandSpotDrag || islandSpotDrag.pointerId !== ev.pointerId) return;
      if (islandSpotDrag.id !== btn.dataset.b) return;
      ev.preventDefault();
      ev.stopPropagation();
      const pct = clientToIslandPct(ev.clientX, ev.clientY, world);
      // Follow the finger freely on land — pad snap waits for drop.
      applyIslandSpotPosDom(islandSpotDrag.id, pct.x, pct.y, { snap: false });
      updateIslandDropTarget(islandSpotDrag.id, pct.x, pct.y);
    });

    const endSpot = (ev: PointerEvent) => {
      if (islandLongPress && islandLongPress.pointerId === ev.pointerId) {
        clearIslandLongPress();
      }
      if (!islandSpotDrag || islandSpotDrag.pointerId !== ev.pointerId) return;
      const dragId = islandSpotDrag.id;
      const pct = clientToIslandPct(ev.clientX, ev.clientY, world);
      applyIslandSpotPosDom(dragId, pct.x, pct.y, { snap: true });
      clearIslandDropTargets();
      viewport.classList.remove("is-spot-dragging");
      btn.classList.remove("is-dragging");
      islandSpotDrag = null;
      islandLayoutSuppressClick = true;
      queueMicrotask(() => {
        islandLayoutSuppressClick = false;
      });
    };
    btn.addEventListener("pointerup", endSpot);
    btn.addEventListener("pointercancel", endSpot);
  });
}

const GAME_VIEWS = new Set<View>([
  "auth",
  "home",
  "summon",
  "enhance",
  "summoner",
  "shop",
  "pond",
  "mine",
  "wish",
  "glory",
  "fusion",
  "party",
  "guild",
  "dojo",
  "stages",
  "battle",
  "result",
]);

function isGameView(v: string): v is View {
  return GAME_VIEWS.has(v as View);
}

function noteViewChange(): void {
  if (view === lastTrackedView) return;
  if (!viewHistoryLock && lastTrackedView !== "auth") {
    const prev = lastTrackedView;
    if (viewHistory[viewHistory.length - 1] !== prev) {
      viewHistory.push(prev);
      if (viewHistory.length > 24) viewHistory.shift();
    }
  }
  lastTrackedView = view;
}

function closeHudSheetsForNav(): void {
  closeSysConfirm();
  settingsOpen = false;
  mailboxOpen = false;
  notifOpen = false;
  summonerPickerOpen = false;
  resMoreOpen = false;
  missionOpen = false;
  communityOpen = false;
  shopOpen = false;
  applySettingsOpen();
  applyMailboxOpen();
  applyNotifOpen();
  applySummonerPickerOpen();
  applyResMoreOpen();
  applyMissionOpen();
  applyCommunityOpen();
  applyShopOpen();
  closeChatOverlay();
  closeDojoInscUpgradeSoft();
}

function applyViewChange(next: View, opts?: { fromBack?: boolean }): void {
  if (next === view) return;
  if (opts?.fromBack) viewHistoryLock = true;
  closeHudSheetsForNav();
  if (view === "result" || view === "battle") {
    autoMode = false;
    clearAutoTimer();
    if (next !== "battle" && next !== "result") {
      battle = null;
      dmgFloats = [];
      if (next === "home") {
        currentStage = null;
        lastReward = null;
        lastScrollGain = 0;
        lastScrollPremiumGain = 0;
  lastScrollLegendGain = 0;
      }
    }
  }
  if (next === "party") {
    preparePartyHall();
  } else if (view === "party") {
    commitPartyDraftOnLeave();
  }
  if (next !== "stages") {
    stagesRegion = null;
    stageEntryId = null;
    stagesDropInfoOpen = false;
    resetCoreStageBindings();
    rememberOverlayClose("stage-prep");
    rememberOverlayClose("stages-region");
  }
  if ((view === "home" || isFacilityView()) && next !== "home" && islandLayoutEdit) {
    if (islandLayoutDraft) writeIslandLayout(islandLayoutDraft);
    islandLayoutEdit = false;
    islandLayoutDraft = null;
    islandSpotDrag = null;
    clearIslandLongPress();
    rememberOverlayClose("island-layout-edit");
  }
  if (next === "enhance") {
    enhanceTab = "monsters";
    selectFirstEnhanceRosterSlot();
  }
  if (next === "stages") {
    patchOnboard({ openedStages: true });
  }
  if (next === "home") {
    closeMonRiteModal();
  }
  if (next === "enhance" || next === "home" || next === "summoner") {
    codexOpen = false;
    codexDetailMonsterId = null;
  }
  const stayOnIsland =
    (view === "home" || isFacilityView(view)) &&
    (next === "home" || isFacilityView(next)) &&
    Boolean(app.querySelector(".home-island"));
  view = next;
  if (stayOnIsland) renderPreservingIsland();
  else render();
  lastTrackedView = view;
  viewHistoryLock = false;
}

function overlayLayerDismissSelector(): string {
  return [
    "button.settings-backdrop",
    "button.stages-region-backdrop",
    "button.stage-prep-backdrop",
    "button.stage-drop-info-backdrop",
    "button.stage-prep-info-backdrop",
    "button[id$='-close']",
    "button[id$='-dismiss']",
    "button[id$='-cancel']",
    "button[id$='-skip']",
    "[data-core-region-close]",
    "[data-core-prep-action='cancel']",
  ].join(", ");
}

function isOverlayIdOpen(id: string): boolean {
  switch (id) {
    case "island-spot-menu":
      return !!islandSpotMenuId;
    case "res-more":
      return resMoreOpen;
    case "gear-bag-filter":
      return gearBagFilterOpen;
    case "island-layout-edit":
      return islandLayoutEdit;
    case "battle-auto-settings":
      return battleAutoSettingsOpen;
    case "stone-result-sheet-layer":
      return stoneResultSheetOpen;
    case "stone-pick-help-layer":
      return stonePickHelpOpen;
    case "battle-skill-info-layer":
      return !!battleSkillInfo;
    case "stages-region":
      return view === "stages" && !!stagesRegion && !stageEntryId;
    case "stage-prep":
      return !!stageEntryId;
    case "onboard-welcome":
      return onboardWelcomeOpen;
    case "sys-confirm-layer":
      return sysConfirmKind !== null;
    case "settings-layer":
      return settingsOpen;
    case "profile-layer":
      return profileOpen;
    case "mailbox-layer":
      return mailboxOpen;
    case "notif-layer":
      return notifOpen;
    case "mission-layer":
      return missionOpen;
    case "community-layer":
      return communityOpen;
    case "guild-form-layer":
      return !!guildFormMode;
    case "shop-layer":
      return shopOpen;
    case "summoner-picker-layer":
      return summonerPickerOpen;
    case "summoner-info-layer":
      return summonerInfoOpen;
    case "chat-layer":
      return chatOpen;
    case "chat-profile-layer":
      return !!chatProfileUid;
    case "power-up-layer":
      return powerUpModalOpen;
    case "evolve-layer":
      return evolveModalOpen;
    case "building-info-layer":
      return !!buildingInfoId;
    case "feature-unlock-layer":
      return !!activeFeatureUnlock();
    case "codex-layer":
      return codexOpen;
    case "forge-reveal-layer":
      return !!forgeReveal;
    case "forge-confirm-layer":
      return !!forgeConfirm;
    case "gear-detail-layer":
      return !!gearDetailTarget;
    case "gear-sell-confirm-layer":
      return gearSellConfirmIndex != null;
    case "gear-enhance-confirm-layer":
      return gearEnhanceConfirmSlot != null;
    case "sym-detail-layer":
      return symbolDetailIndex != null;
    case "sym-bag-expand-layer":
      return symbolBagExpandOpen;
    case "gear-bag-expand-layer":
      return gearBagExpandOpen;
    case "summon-detail-layer":
      return !!summonDetailUid;
    case "summon-multi-result-layer":
      return summonMultiRevealOpen;
    case "stage-prep-info-layer":
      return !!stagePrepInfo;
    case "stage-drop-info-layer":
      return stagesDropInfoOpen;
    default: {
      const el = app.querySelector<HTMLElement>(`#${CSS.escape(id)}`);
      return !!el && overlayDomIsOpen(el);
    }
  }
}

